var OT_VERSES = [{"book":"창세기","ref":"창세기 3:15","topic":"원시복음, 창세기 주제","text":"내가 너로 여자와 원수가 되게 하고 네 후손도 여자의 후손과 원수가 되게 하리니 여자의 후손은 네 머리를 상하게 할 것이요 / 너는 그의 발꿈치를 상하게 할 것이니라 하시고"},{"book":"창세기","ref":"창세기 12:1","topic":"하나님의 부름과 약속","text":"여호와께서 아브람에게 이르시되 너는 너의 고향과 친척과 아버지의 집을 떠나 내가 네게 보여 줄 땅으로 가라"},{"book":"창세기","ref":"창세기 12:2","topic":"하나님의 부름과 약속","text":"내가 너로 큰 민족을 이루고 네게 복을 주어 네 이름을 창대하게 하리니 너는 복이 될지라"},{"book":"창세기","ref":"창세기 22:12","topic":"하나님 경외","text":"사자가 이르시되 그 아이에게 네 손을 대지 말라 그에게 아무 일도 하지 말라 네가 네 아들 네 독자까지도 내게 아끼지 아니하였으니 내가 이제야 네가 하나님을 경외하는 줄을 아노라"},{"book":"창세기","ref":"창세기 49:10","topic":"메시아 예언","text":"규가 유다를 떠나지 아니하며 / 통치자의 지팡이가 그 발 사이에서 떠나지 아니하기를 실로가 오시기까지 이르리니 그에게 모든 백성이 복종하리로다"},{"book":"출애굽기","ref":"출애굽기 3:14","topic":"하나님의 이름과 존재","text":"하나님이 모세에게 이르시되 나는 스스로 있는 자이니라 또 이르시되 너는 이스라엘 자손에게 이같이 이르기를 스스로 있는 자가 나를 너희에게 보내셨다 하라"},{"book":"출애굽기","ref":"출애굽기 12:13","topic":"유월절 의미","text":"내가 애굽 땅을 칠 때에 그 피가 너희가 사는 집에 있어서 너희를 위하여 표적이 될지라 내가 피를 볼 때에 너희를 넘어가리니 재앙이 너희에게 내려 멸하지 아니하리라"},{"book":"출애굽기","ref":"출애굽기 19:5","topic":"시내산 언약의 의미","text":"세계가 다 내게 속하였나니 너희가 내 말을 잘 듣고 내 언약을 지키면 너희는 모든 민족 중에서 내 소유가 되겠고"},{"book":"출애굽기","ref":"출애굽기 19:6","topic":"시내산 언약의 의미","text":"너희가 내게 대하여 제사장 나라가 되며 거룩한 백성이 되리라 너는 이 말을 이스라엘 자손에게 전할지니라"},{"book":"출애굽기","ref":"출애굽기 25:21","topic":"성소와 하나님의 통치","text":"속죄소를 궤 위에 얹고 내가 네게 줄 증거판을 궤 속에 넣으라"},{"book":"출애굽기","ref":"출애굽기 25:22","topic":"성소와 하나님의 통치","text":"거기서 내가 너와 만나고 속죄소 위 곧 증거궤 위에 있는 두 그룹 사이에서 내가 이스라엘 자손을 위하여 네게 명령할 모든 일을 네게 이르리라"},{"book":"레위기","ref":"레위기 16:29","topic":"속죄일","text":"너희는 영원히 이 규례를 지킬지니라 일곱째 달 곧 그 달 십일에 너희는 스스로 괴롭게 하고 / 아무 일도 하지 말되 본토인이든지 너희 중에 거류하는 거류민이든지 그리하라"},{"book":"레위기","ref":"레위기 16:30","topic":"속죄일","text":"이 날에 너희를 위하여 속죄하여 너희를 정결하게 하리니 너희의 모든 죄에서 너희가 여호와 앞에 정결하리라"},{"book":"레위기","ref":"레위기 25:10","topic":"희년","text":"너희는 오십 년째 해를 거룩하게 하여 그 땅에 있는 모든 주민을 위하여 자유를 공포하라 이 해는 너희에게 희년이니 너희는 각각 자기의 소유지로 돌아가며 각각 자기의 가족에게로 돌아갈지며"},{"book":"민수기","ref":"민수기 6:24","topic":"축복 기원","text":"여호와는 네게 복을 주시고 너를 지키시기를 원하며"},{"book":"민수기","ref":"민수기 6:25","topic":"축복 기원","text":"여호와는 그의 얼굴을 네게 비추사 은혜 베푸시기를 원하며"},{"book":"민수기","ref":"민수기 6:26","topic":"축복 기원","text":"여호와는 그 얼굴을 네게로 향하여 드사 평강 주시기를 원하노라 할지니라 하라"},{"book":"민수기","ref":"민수기 23:19","topic":"하나님의 신실함","text":"하나님은 사람이 아니시니 거짓말을 하지 않으시고 인생이 아니시니 / 후회가 없으시도다 어찌 그 말씀하신 바를 행하지 않으시며 하신 말씀을 실행하지 않으시랴"},{"book":"민수기","ref":"민수기 24:17","topic":"발람을 통한 메시아 예언","text":"내가 그를 보아도 이때의 일이 아니며 내가 그를 바라보아도 가까운 일이 아니로다 한 별이 야곱에게서 나오며 한 규가 이스라엘에게서 일어나서 모압을 이쪽에서 저쪽까지 쳐서 무찌르고 또 셋의 자식들을 다 멸하리로다"},{"book":"신명기","ref":"신명기 6:4","topic":"여호와 사랑","text":"이스라엘아 들으라 우리 하나님 여호와는 오직 유일한 여호와이시니"},{"book":"신명기","ref":"신명기 6:5","topic":"여호와 사랑","text":"너는 마음을 다하고 뜻을 다하고 / 힘을 다하여 네 하나님 여호와를 사랑하라"},{"book":"신명기","ref":"신명기 9:5","topic":"가나안 민족을 쫓아낸 이유","text":"네가 가서 그 땅을 차지함은 네 공의로 말미암음도 아니며 네 마음이 정직함으로 말미암음도 아니요 이 민족들이 악함으로 말미암아 네 하나님 여호와께서 그들을 네 앞에서 쫓아내심이라 여호와께서 이같이 하심은 네 조상 아브라함과 이삭과 야곱에게 하신 맹세를 이루려 하심이니라"},{"book":"신명기","ref":"신명기 10:17","topic":"여호와의 정의와 사랑","text":"너희의 하나님 여호와는 신 가운데 신이시며 주 가운데 주시요 크고 능하시며 두려우신 하나님이시라 사람을 외모로 보지 아니하시며 뇌물을 받지 아니하시고"},{"book":"신명기","ref":"신명기 10:18","topic":"여호와의 정의와 사랑","text":"고아와 과부를 위하여 정의를 행하시며 나그네를 사랑하여 그에게 떡과 옷을 주시나니"},{"book":"신명기","ref":"신명기 18:18","topic":"모세와 같은 선지자","text":"내가 그들의 형제 중에서 너와 같은 선지자 하나를 그들을 위하여 일으키고 내 말을 그 입에 두리니 내가 그에게 명령하는 것을 그가 무리에게 다 말하리라"},{"book":"신명기","ref":"신명기 30:15","topic":"언약의 축복","text":"보라 내가 오늘 생명과 복과 사망과 화를 네 앞에 두었나니"},{"book":"신명기","ref":"신명기 30:16","topic":"언약의 축복","text":"곧 내가 오늘 네게 명령하여 네 하나님 여호와를 사랑하고 그 모든 길로 행하며 그의 명령과 규례와 법도를 지키라 하는 것이라 그리하면 네가 생존하며 / 번성할 것이요 또 네 하나님 여호와께서 네가 가서 차지할 땅에서 네게 복을 주실 것임이니라"},{"book":"여호수아","ref":"여호수아 24:15","topic":"여호와만 섬기라","text":"만일 여호와를 섬기는 것이 너희에게 좋지 않게 보이거든 너희 조상들이 강 저쪽에서 섬기던 신들이든지 또는 너희가 거주하는 땅에 있는 아모리 족속의 신들이든지 너희가 섬길 자를 오늘 택하라 오직 나와 내 집은 여호와를 섬기겠노라 하니"},{"book":"사사기","ref":"사사기 21:25","topic":"사사 시대의 상황, 왕이 필요한 이유","text":"그 때에 이스라엘에 왕이 없으므로 사람이 각기 자기의 소견에 옳은 대로 행하였더라"},{"book":"사무엘상","ref":"사무엘상 2:10","topic":"한나의 기도, 메시아 왕","text":"여호와를 대적하는 자는 산산이 깨어질 것이라 하늘에서 우레로 그들을 치시리로다 여호와께서 땅 끝까지 심판을 내리시고 자기 왕에게 힘을 주시며 자기의 기름 부음을 받은 자의 뿔을 높이시리로다 하니라"},{"book":"사무엘상","ref":"사무엘상 15:22","topic":"순종과 제사","text":"사무엘이 이르되 여호와께서 번제와 다른 제사를 그의 목소리를 청종하는 것을 좋아하심 같이 좋아하시겠나이까 순종이 제사보다 낫고 듣는 것이 숫양의 기름보다 나으니"},{"book":"사무엘상","ref":"사무엘상 16:7","topic":"중심을 보시는 하나님","text":"여호와께서 사무엘에게 이르시되 그의 용모와 키를 보지 말라 내가 이미 그를 버렸노라 내가 보는 것은 사람과 같지 아니하니 / 사람은 외모를 보거니와 나 여호와는 중심을 보느니라 하시더라"},{"book":"사무엘상","ref":"사무엘상 17:45","topic":"여호와의 이름으로","text":"다윗이 블레셋 사람에게 이르되 너는 칼과 창과 단창으로 내게 나아 오거니와 나는 만군의 여호와의 이름 곧 네가 모욕하는 이스라엘 군대의 하나님의 이름으로 네게 나아가노라"},{"book":"사무엘하","ref":"사무엘하 7:19","topic":"다윗 언약","text":"주 여호와여 주께서 이것을 오히려 적게 여기시고 또 종의 집에 있을 먼 장래의 일까지도 말씀하셨나이다 주 여호와여 이것이 사람의 법이니이다"},{"book":"열왕기상","ref":"열왕기상 2:4","topic":"열왕기서의 주제","text":"여호와께서 내 일에 대하여 말씀하시기를 만일 네 자손들이 그들의 길을 삼가 마음을 다하고 / 성품을 다하여 진실히 내 앞에서 행하면 이스라엘 왕위에 오를 사람이 네게서 끊어지지 아니하리라 하신 말씀을 확실히 이루게 하시리라"},{"book":"열왕기상","ref":"열왕기상 8:10","topic":"성전과 하나님의 영광","text":"제사장이 성소에서 나올 때에 구름이 여호와의 성전에 가득하매"},{"book":"열왕기상","ref":"열왕기상 8:11","topic":"성전과 하나님의 영광","text":"제사장이 그 구름으로 말미암아 능히 서서 섬기지 못하였으니 이는 여호와의 영광이 여호와의 성전에 가득함이었더라"},{"book":"열왕기상","ref":"열왕기상 8:27","topic":"하나님의 위대함","text":"하나님이 참으로 땅에 거하시리이까 하늘과 하늘들의 하늘이라도 주를 용납하지 못하겠거든 하물며 내가 건축한 이 성전이오리이까"},{"book":"열왕기상","ref":"열왕기상 12:7","topic":"섬기는 왕","text":"대답하여 이르되 왕이 만일 오늘 이 백성을 섬기는 자가 되어 그들을 섬기고 좋은 말로 대답하여 이르시면 그들이 영원히 왕의 종이 되리이다 하나"},{"book":"열왕기상","ref":"열왕기상 18:36","topic":"엘리야의 심정","text":"저녁 소제 드릴 때에 이르러 선지자 엘리야가 나아가서 말하되 / 아브라함과 이삭과 이스라엘의 하나님 여호와여 주께서 이스라엘 중에서 하나님이신 것과 내가 주의 종인 것과 내가 주의 말씀대로 이 모든 일을 행하는 것을 오늘 알게 하옵소서"},{"book":"열왕기하","ref":"열왕기하 5:26","topic":"선지자 생도의 마음가짐","text":"엘리사가 이르되 한 사람이 수레에서 내려 너를 맞이할 때에 내 마음이 함께 가지 아니하였느냐 지금이 어찌 은을 받으며 옷을 받으며 감람원이나 포도원이나 양이나 소나 남종이나 여종을 받을 때이냐"},{"book":"역대상","ref":"역대상 22:5","topic":"성전 건축 준비","text":"다윗이 이르되 내 아들 솔로몬은 어리고 미숙하고 / 여호와를 위하여 건축할 성전은 극히 웅장하여 만국에 명성과 영광이 있게 하여야 할지라 그러므로 내가 이제 그것을 위하여 준비하리라 하고 다윗이 죽기 전에 많이 준비하였더라"},{"book":"역대하","ref":"역대하 3:1","topic":"성전 터","text":"솔로몬이 예루살렘 모리아 산에 여호와의 전 건축하기를 시작하니 / 그 곳은 전에 여호와께서 그의 아버지 다윗에게 나타나신 곳이요 여부스 사람 오르난의 타작마당에 다윗이 정한 곳이라"},{"book":"역대하","ref":"역대하 36:21","topic":"포로와 땅의 안식","text":"이에 토지가 황폐하여 땅이 안식년을 누림 같이 안식하여 칠십 년을 지냈으니 여호와께서 예레미야의 입으로 하신 말씀이 이루어졌더라"},{"book":"에스라","ref":"에스라 1:2","topic":"1차 포로 귀환","text":"바사 왕 고레스는 말하노니 하늘의 하나님 여호와께서 세상 모든 나라를 내게 주셨고 나에게 명령하사 유다 예루살렘에 성전을 건축하라 하셨나니"},{"book":"느헤미야","ref":"느헤미야 8:9","topic":"에스라와 율법 강독","text":"백성이 율법의 말씀을 듣고 다 우는지라 총독 느헤미야와 제사장 겸 학사 에스라와 백성을 가르치는 레위 사람들이 모든 백성에게 이르기를 오늘은 너희 하나님 여호와의 성일이니 슬퍼하지 말며 울지 말라 하고"},{"book":"에스더","ref":"에스더 4:14","topic":"하나님의 섭리","text":"이때에 네가 만일 잠잠하여 말이 없으면 유다인은 다른 데로 말미암아 놓임과 구원을 얻으려니와 너와 네 아버지 집은 멸망하리라 네가 왕후의 자리를 얻은 것이 이때를 위함이 아닌지 누가 알겠느냐 하니"},{"book":"욥기","ref":"욥기 2:3","topic":"욥의 하나님 경외","text":"여호와께서 사탄에게 이르시되 네가 내 종 욥을 주의하여 보았느냐 그와 같이 온전하고 정직하여 하나님을 경외하며 / 악에서 떠난 자가 세상에 없느니라 네가 나를 충동하여 까닭 없이 그를 치게 하였어도 그가 여전히 자기의 온전함을 굳게 지켰느니라"},{"book":"욥기","ref":"욥기 19:25","topic":"부활과 메시아","text":"내가 알기에는 나의 대속자가 살아 계시니 / 마침내 그가 땅 위에 서실 것이라"},{"book":"욥기","ref":"욥기 19:26","topic":"부활과 메시아","text":"내 가죽이 벗김을 당한 뒤에도 내가 육체 밖에서 하나님을 보리라"},{"book":"시편","ref":"시편 2:7","topic":"메시아 예언","text":"내가 여호와의 명령을 전하노라 여호와께서 내게 이르시되 너는 내 아들이라 오늘 내가 너를 낳았도다"},{"book":"시편","ref":"시편 2:8","topic":"메시아 예언","text":"내게 구하라 내가 이방 나라를 네 유업으로 주리니 네 소유가 땅 끝까지 이르리로다"},{"book":"시편","ref":"시편 14:1","topic":"어리석은 자","text":"어리석은 자는 그의 마음에 이르기를 하나님이 없다 하는도다 그들은 부패하고 / 그 행실이 가증하니 선을 행하는 자가 없도다"},{"book":"시편","ref":"시편 14:2","topic":"어리석은 자","text":"여호와께서 하늘에서 인생을 굽어살피사 지각이 있어 하나님을 찾는 자가 있는가 보려 하신즉"},{"book":"시편","ref":"시편 14:3","topic":"어리석은 자","text":"다 치우쳐 함께 더러운 자가 되고 선을 행하는 자가 없으니 하나도 없도다"},{"book":"시편","ref":"시편 23:1","topic":"하나님의 인도","text":"여호와는 나의 목자시니 / 내게 부족함이 없으리로다"},{"book":"시편","ref":"시편 23:2","topic":"하나님의 인도","text":"그가 나를 푸른 풀밭에 누이시며 쉴 만한 물 가로 인도하시는도다"},{"book":"시편","ref":"시편 23:3","topic":"하나님의 인도","text":"내 영혼을 소생시키시고 자기 이름을 위하여 의의 길로 인도하시는도다"},{"book":"시편","ref":"시편 42:1","topic":"하나님을 사모함","text":"1 하나님이여 사슴이 시냇물을 찾기에 갈급함 같이 내 영혼이 주를 찾기에 갈급하니이다"},{"book":"시편","ref":"시편 48:1","topic":"여호와와 시온 찬양","text":"여호와는 위대하시니 / 우리 하나님의 성, 거룩한 산에서 극진히 찬양 받으시리로다"},{"book":"시편","ref":"시편 48:2","topic":"여호와와 시온 찬양","text":"터가 높고 아름다워 온 세계가 즐거워함이여 큰 왕의 성 곧 북방에 있는 시온 산이 그러하도다"},{"book":"시편","ref":"시편 51:9","topic":"회개와 회복","text":"주의 얼굴을 내 죄에서 돌이키시고 내 모든 죄악을 지워 주소서"},{"book":"시편","ref":"시편 51:10","topic":"회개와 회복","text":"하나님이여 내 속에 정한 마음을 창조하시고 내 안에 정직한 영을 새롭게 하소서"},{"book":"시편","ref":"시편 51:11","topic":"회개와 회복","text":"나를 주 앞에서 쫓아내지 마시며 주의 성령을 내게서 거두지 마소서"},{"book":"시편","ref":"시편 51:12","topic":"회개와 회복","text":"주의 구원의 즐거움을 내게 회복시켜 주시고 자원하는 심령을 주사 나를 붙드소서"},{"book":"시편","ref":"시편 73:25","topic":"하나님 신뢰","text":"하늘에서는 주 외에 누가 내게 있으리요 땅에서는 주 밖에 내가 사모할 이 없나이다"},{"book":"시편","ref":"시편 73:26","topic":"하나님 신뢰","text":"내 육체와 마음은 쇠약하나 하나님은 내 마음의 반석이시요 영원한 분깃이시라"},{"book":"시편","ref":"시편 96:10","topic":"하나님의 공의","text":"모든 나라 가운데서 이르기를 여호와께서 다스리시니 / 세계가 굳게 서고 흔들리지 않으리라 그가 만민을 공평하게 심판하시리라 할지로다"},{"book":"시편","ref":"시편 110:1","topic":"메시아의 제사장직","text":"여호와께서 내 주에게 말씀하시기를 내가 네 원수들로 네 발판이 되게 하기까지 너는 내 오른쪽에 앉아 있으라 하셨도다"},{"book":"시편","ref":"시편 110:4","topic":"메시아의 제사장직","text":"여호와는 맹세하고 변하지 아니하시리라 이르시기를 너는 멜기세덱의 서열을 따라 영원한 제사장이라 하셨도다"},{"book":"시편","ref":"시편 121:3","topic":"하나님의 보호","text":"여호와께서 너를 실족하지 아니하게 하시며 너를 지키시는 이가 졸지 아니하시리로다"},{"book":"시편","ref":"시편 121:4","topic":"하나님의 보호","text":"이스라엘을 지키시는 이는 졸지도 아니하시고 주무시지도 아니하시리로다"},{"book":"잠언","ref":"잠언 1:7","topic":"지식의 근본","text":"여호와를 경외하는 것이 지식의 근본이거늘 미련한 자는 지혜와 훈계를 멸시하느니라"},{"book":"잠언","ref":"잠언 3:5","topic":"여호와를 신뢰","text":"너는 마음을 다하여 여호와를 신뢰하고 / 네 명철을 의지하지 말라"},{"book":"잠언","ref":"잠언 3:6","topic":"여호와를 신뢰","text":"너는 범사에 그를 인정하라 그리하면 네 길을 지도하시리라"},{"book":"잠언","ref":"잠언 8:17","topic":"지혜 사랑","text":"나를 사랑하는 자들이 나의 사랑을 입으며 나를 간절히 찾는 자가 나를 만날 것이니라"},{"book":"잠언","ref":"잠언 8:18","topic":"지혜 사랑","text":"부귀가 내게 있고 장구한 재물과 공의도 그러하니라"},{"book":"잠언","ref":"잠언 19:17","topic":"선행","text":"가난한 자를 불쌍히 여기는 것은 여호와께 꾸어 드리는 것이니 그의 선행을 그에게 갚아 주시리라"},{"book":"잠언","ref":"잠언 25:21","topic":"원수 사랑","text":"네 원수가 배고파하거든 음식을 먹이고 목말라하거든 물을 마시게 하라"},{"book":"잠언","ref":"잠언 25:22","topic":"원수 사랑","text":"그리 하는 것은 핀 숯을 그의 머리에 놓는 것과 일반이요 / 여호와께서 네게 갚아 주시리라"},{"book":"잠언","ref":"잠언 29:18","topic":"율법과 복","text":"묵시가 없으면 백성이 방자히 행하거니와 율법을 지키는 자는 복이 있느니라"},{"book":"전도서","ref":"전도서 3:11","topic":"측량할 수 없는 하나님의 일","text":"하나님이 모든 것을 지으시되 때를 따라 아름답게 하셨고 또 사람들에게는 영원을 사모하는 마음을 주셨느니라 그러나 하나님이 하시는 일의 시종을 사람으로 측량할 수 없게 하셨도다"},{"book":"전도서","ref":"전도서 9:9","topic":"아내와 가정","text":"네 헛된 평생의 모든 날 곧 하나님이 해 아래에서 네게 주신 모든 헛된 날에 네가 사랑하는 아내와 함께 즐겁게 살지어다 그것이 네가 평생에 해 아래에서 수고하고 얻은 네 몫이니라"},{"book":"전도서","ref":"전도서 9:10","topic":"아내와 가정","text":"네 손이 일을 얻는 대로 힘을 다하여 할지어다 네가 장차 들어갈 스올에는 일도 없고 계획도 없고 지식도 없고 지혜도 없음이니라"},{"book":"전도서","ref":"전도서 12:13","topic":"하나님 경외와 사람의 본분","text":"일의 결국을 다 들었으니 하나님을 경외하고 / 그의 명령들을 지킬지어다 이것이 모든 사람의 본분이니라"},{"book":"이사야","ref":"이사야 1:18","topic":"죄 용서","text":"여호와께서 말씀하시되 오라 우리가 서로 변론하자 너희의 죄가 주홍 같을지라도 눈과 같이 희어질 것이요 / 진홍 같이 붉을지라도 양털 같이 희게 되리라"},{"book":"이사야","ref":"이사야 5:7","topic":"악한 포도 열매","text":"무릇 만군의 여호와의 포도원은 이스라엘 족속이요 / 그가 기뻐하시는 나무는 유다 사람이라 그들에게 정의를 바라셨더니 도리어 포학이요 그들에게 공의를 바라셨더니 도리어 부르짖음이었도다"},{"book":"이사야","ref":"이사야 6:5","topic":"이사야의 소명","text":"그 때에 내가 말하되 화로다 나여 망하게 되었도다 나는 입술이 부정한 사람이요 / 나는 입술이 부정한 백성 중에 거주하면서 만군의 여호와이신 왕을 뵈었음이로다 하였더라"},{"book":"이사야","ref":"이사야 7:14","topic":"메시아 탄생","text":"그러므로 주께서 친히 징조를 너희에게 주실 것이라 보라 처녀가 잉태하여 아들을 낳을 것이요 / 그의 이름을 임마누엘이라 하리라"},{"book":"이사야","ref":"이사야 9:6","topic":"메시아 탄생","text":"이는 한 아기가 우리에게 났고 한 아들을 우리에게 주신 바 되었는데 그의 어깨에는 정사를 메었고 그의 이름은 기묘자라, 모사라, 전능하신 하나님이라, 영존하시는 아버지라, 평강의 왕이라 할 것임이라"},{"book":"이사야","ref":"이사야 40:3","topic":"메시아 오심을 예비","text":"외치는 자의 소리여 이르되 너희는 광야에서 여호와의 길을 예비하라 사막에서 우리 하나님의 대로를 평탄하게 하라"},{"book":"이사야","ref":"이사야 40:4","topic":"메시아 오심을 예비","text":"골짜기마다 돋우어지며 산마다, 언덕마다 낮아지며 고르지 아니한 곳이 평탄하게 되며 험한 곳이 평지가 될 것이요"},{"book":"이사야","ref":"이사야 40:5","topic":"메시아 오심을 예비","text":"여호와의 영광이 나타나고 모든 육체가 그것을 함께 보리라 이는 여호와의 입이 말씀하셨느니라"},{"book":"이사야","ref":"이사야 53:4","topic":"메시아의 고난","text":"그는 실로 우리의 질고를 지고 우리의 슬픔을 당하였거늘 우리는 생각하기를 그는 징벌을 받아 하나님께 맞으며 고난을 당한다 하였노라"},{"book":"이사야","ref":"이사야 53:12","topic":"메시아 고난의 목적","text":"그러므로 내가 그에게 존귀한 자와 함께 몫을 받게 하며 강한 자와 함께 탈취한 것을 나누게 하리니 이는 그가 자기 영혼을 버려 사망에 이르게 하며 / 범죄자 중 하나로 헤아림을 받았음이니라 그러나 그가 많은 사람의 죄를 담당하며 범죄자를 위하여 기도하였느니라"},{"book":"이사야","ref":"이사야 61:1","topic":"메시아의 사역","text":"주 여호와의 영이 내게 내리셨으니 이는 여호와께서 내게 기름을 부으사 가난한 자에게 아름다운 소식을 전하게 하려 하심이라 나를 보내사 마음이 상한 자를 고치며 포로된 자에게 자유를, 갇힌 자에게 놓임을 선포하며"},{"book":"이사야","ref":"이사야 61:2","topic":"메시아의 사역","text":"여호와의 은혜의 해와 우리 하나님의 보복의 날을 선포하여 모든 슬픈 자를 위로하되"},{"book":"예레미야","ref":"예레미야 1:10","topic":"선지자의 소명","text":"보라 내가 오늘 너를 여러 나라와 여러 왕국 위에 세워 네가 그것들을 뽑고 파괴하며 / 파멸하고 넘어뜨리며 건설하고 심게 하였느니라 하시니라"},{"book":"예레미야","ref":"예레미야 20:9","topic":"선지자의 마음","text":"내가 다시는 여호와를 선포하지 아니하며 / 그의 이름으로 말하지 아니하리라 하면 나의 마음이 불붙는 것 같아서 골수에 사무치니 답답하여 견딜 수 없나이다"},{"book":"예레미야","ref":"예레미야 29:10","topic":"포로기 70년","text":"여호와께서 이와 같이 말씀하시니라 바벨론에서 칠십 년이 차면 내가 너희를 돌보고 나의 선한 말을 너희에게 성취하여 너희를 이곳으로 돌아오게 하리라"},{"book":"예레미야","ref":"예레미야 31:33","topic":"새 언약","text":"그러나 그 날 후에 내가 이스라엘 집과 맺을 언약은 이러하니 / 곧 내가 나의 법을 그들의 속에 두며 그들의 마음에 기록하여 나는 그들의 하나님이 되고 그들은 내 백성이 될 것이라 여호와의 말씀이니라"},{"book":"에스겔","ref":"에스겔 3:17","topic":"선지자 사역","text":"인자야 내가 너를 이스라엘 족속의 파수꾼으로 세웠으니 너는 내 입의 말을 듣고 나를 대신하여 그들을 깨우치라"},{"book":"에스겔","ref":"에스겔 11:22","topic":"하나님 영광이 떠남","text":"그 때에 그룹들이 날개를 드는데 바퀴도 그 곁에 있고 이스라엘 하나님의 영광도 그 위에 덮였더니"},{"book":"에스겔","ref":"에스겔 11:23","topic":"하나님 영광이 떠남","text":"여호와의 영광이 성읍 가운데에서부터 올라가 성읍 동쪽 산에 머무르고"},{"book":"에스겔","ref":"에스겔 36:26","topic":"성령 강림","text":"또 새 영을 너희 속에 두고 새 마음을 너희에게 주되 너희 육신에서 굳은 마음을 제거하고 / 부드러운 마음을 줄 것이며"},{"book":"에스겔","ref":"에스겔 36:27","topic":"성령 강림","text":"또 내 영을 너희 속에 두어 너희로 내 율례를 행하게 하리니 너희가 내 규례를 지켜 행할지라"},{"book":"에스겔","ref":"에스겔 47:12","topic":"에덴의 회복","text":"강 좌우 가에는 각종 먹을 과실나무가 자라서 그 잎이 시들지 아니하며 열매가 끊이지 아니하고 / 달마다 새 열매를 맺으리니 그 물이 성소를 통하여 나옴이라 그 열매는 먹을 만하고 그 잎사귀는 약 재료가 되리라"},{"book":"다니엘","ref":"다니엘 2:21","topic":"전지하신 하나님","text":"그는 때와 계절을 바꾸시며 왕들을 폐하시고 왕들을 세우시며 지혜자에게 지혜를 주시고 총명한 자에게 지식을 주시는도다"},{"book":"다니엘","ref":"다니엘 2:22","topic":"전지하신 하나님","text":"그는 깊고 은밀한 일을 나타내시고 어두운 데에 있는 것을 아시며 또 빛이 그와 함께 있도다"},{"book":"다니엘","ref":"다니엘 7:13","topic":"메시아의 나라","text":"내가 또 밤 환상 중에 보니 인자 같은 이가 하늘 구름을 타고 와서 옛적부터 항상 계신 이에게 나아가 그 앞으로 인도되매"},{"book":"다니엘","ref":"다니엘 7:14","topic":"메시아의 나라","text":"그에게 권세와 영광과 나라를 주고 모든 백성과 나라들과 다른 언어를 말하는 모든 자들이 그를 섬기게 하였으니 그의 권세는 소멸되지 아니하는 영원한 권세요 그의 나라는 멸망하지 아니할 것이니라"},{"book":"다니엘","ref":"다니엘 9:24","topic":"메시아 오심","text":"네 백성과 네 거룩한 성을 위하여 일흔 이레를 기한으로 정하였나니 허물이 그치며 죄가 끝나며 죄악이 용서되며 영원한 의가 드러나며 환상과 예언이 응하며 / 또 지극히 거룩한 이가 기름 부음을 받으리라"},{"book":"호세아","ref":"호세아 4:6","topic":"율법을 잊은 자","text":"내 백성이 지식이 없으므로 망하는도다 네가 지식을 버렸으니 나도 너를 버려 내 제사장이 되지 못하게 할 것이요 / 네가 네 하나님의 율법을 잊었으니 나도 네 자녀들을 잊어버리리라"},{"book":"호세아","ref":"호세아 6:1","topic":"회개","text":"오라 우리가 여호와께로 돌아가자 여호와께서 우리를 찢으셨으나 도로 낫게 하실 것이요 / 우리를 치셨으나 싸매어 주실 것임이라"},{"book":"요엘","ref":"요엘 2:28","topic":"성령 주심","text":"그 후에 내가 내 영을 만민에게 부어 주리니 너희 자녀들이 장래 일을 말할 것이며 너희 늙은이는 꿈을 꾸며 너희 젊은이는 이상을 볼 것이며"},{"book":"요엘","ref":"요엘 2:29","topic":"성령 주심","text":"그 때에 내가 또 내 영을 남종과 여종에게 부어 줄 것이며"},{"book":"아모스","ref":"아모스 5:18","topic":"여호와의 날","text":"화 있을진저 여호와의 날을 사모하는 자여 너희가 어찌하여 여호와의 날을 사모하느냐 그 날은 어둠이요 빛이 아니라"},{"book":"아모스","ref":"아모스 5:24","topic":"정의","text":"오직 정의를 물 같이, 공의를 마르지 않는 강 같이 흐르게 할지어다"},{"book":"아모스","ref":"아모스 9:7","topic":"세상을 주관하는 하나님","text":"여호와의 말씀이니라 이스라엘 자손들아 너희는 내게 구스 족속 같지 아니하냐 내가 이스라엘을 애굽 땅에서, 블레셋 사람을 갑돌에서, 아람 사람을 기르에서 올라오게 하지 아니하였느냐"},{"book":"요나","ref":"요나 4:10","topic":"불신 자에 대한 하나님의 마음","text":"여호와께서 이르시되 네가 수고도 아니하였고 재배도 아니하였고 하룻밤에 났다가 하룻밤에 말라 버린 이 박 넝쿨을 아꼈거든"},{"book":"요나","ref":"요나 4:11","topic":"불신 자에 대한 하나님의 마음","text":"하물며 이 큰 성읍 니느웨에는 좌우를 분변하지 못하는 자가 십이만여 명이요 / 가축도 많이 있나니 내가 어찌 아끼지 아니하겠느냐 하시니라"},{"book":"미가","ref":"미가 4:1","topic":"이방인의 회복","text":"끝날에 이르러는 여호와의 전의 산이 산들의 꼭대기에 굳게 서며 작은 산들 위에 뛰어나고 민족들이 그리로 몰려갈 것이라"},{"book":"미가","ref":"미가 4:2","topic":"이방인의 회복","text":"곧 많은 이방 사람들이 가며 이르기를 오라 우리가 여호와의 산에 올라가서 야곱의 하나님의 전에 이르자 그가 그의 도를 가지고 우리에게 가르치실 것이니라 우리가 그의 길로 행하리라 하리니 이는 율법이 시온에서부터 나올 것이요 / 여호와의 말씀이 예루살렘에서부터 나올 것임이라"},{"book":"미가","ref":"미가 5:2","topic":"메시아 탄생지","text":"베들레헴 에브라다야 너는 유다 족속 중에 작을지라도 이스라엘을 다스릴 자가 네게서 내게로 나올 것이라 그의 근본은 상고에, 영원에 있느니라"},{"book":"미가","ref":"미가 6:7","topic":"여호와가 기뻐하시는 것","text":"여호와께서 천천의 숫양이나 만만의 강물 같은 기름을 기뻐하실까 내 허물을 위하여 내 맏아들을, 내 영혼의 죄로 말미암아 내 몸의 열매를 드릴까"},{"book":"미가","ref":"미가 6:8","topic":"여호와가 기뻐하시는 것","text":"사람아 주께서 선한 것이 무엇임을 네게 보이셨나니 여호와께서 네게 구하시는 것은 오직 정의를 행하며 / 인자를 사랑하며 겸손하게 네 하나님과 함께 행하는 것이 아니냐"},{"book":"나훔","ref":"나훔 1:2","topic":"하나님의 진노","text":"여호와는 질투하시며 보복하시는 하나님이시니라 여호와는 보복하시며 진노하시되 자기를 거스르는 자에게 여호와는 보복하시며 자기를 대적하는 자에게 진노를 품으시며"},{"book":"나훔","ref":"나훔 1:3","topic":"하나님의 진노","text":"여호와는 노하기를 더디 하시며 권능이 크시며 벌 받을 자를 결코 내버려두지 아니 하시느니라 여호와의 길은 회오리바람과 광풍에 있고 구름은 그의 발의 티끌이로다"},{"book":"하박국","ref":"하박국 2:4","topic":"의인과 믿음","text":"보라 그의 마음은 교만하며 / 그 속에서 정직하지 못하나 의인은 그의 믿음으로 말미암아 살리라"},{"book":"하박국","ref":"하박국 2:14","topic":"여호와의 영광","text":"이는 물이 바다를 덮음 같이 여호와의 영광을 인정하는 것이 세상에 가득함이니라"},{"book":"스바냐","ref":"스바냐 3:17","topic":"여호와의 기쁨","text":"너의 하나님 여호와가 너의 가운데에 계시니 / 그는 구원을 베푸실 전능자이시라 그가 너로 말미암아 기쁨을 이기지 못하시며 너를 잠잠히 사랑하시며 너로 말미암아 즐거이 부르며 기뻐하시리라 하리라"},{"book":"학개","ref":"학개 2:6","topic":"시온의 회복","text":"만군의 여호와가 이같이 말하노라 조금 있으면 내가 하늘과 땅과 바다와 육지를 진동시킬 것이요"},{"book":"학개","ref":"학개 2:7","topic":"시온의 회복","text":"또한 모든 나라를 진동시킬 것이며 모든 나라의 보배가 이르리니 내가 이 성전에 영광이 충만하게 하리라 만군의 여호와의 말이니라"},{"book":"스가랴","ref":"스가랴 3:8","topic":"메시아의 대속","text":"대제사장 여호수아야 너와 네 앞에 앉은 네 동료들은 내 말을 들을 것이니라 이들은 예표의 사람들이라 내가 내 종 싹을 나게 하리라"},{"book":"스가랴","ref":"스가랴 3:9","topic":"메시아의 대속","text":"만군의 여호와가 말하노라 내가 너 여호수아 앞에 세운 돌을 보라 한 돌에 일곱 눈이 있느니라 내가 거기에 새길 것을 새기며 이 땅의 죄악을 하루에 제거하리라"},{"book":"스가랴","ref":"스가랴 4:6","topic":"성전 재건과 성령","text":"그가 내게 대답하여 이르되 여호와께서 스룹바벨에게 하신 말씀이 이러하니라 만군의 여호와께서 말씀하시되 이는 힘으로 되지 아니하며 / 능력으로 되지 아니하고 오직 나의 영으로 되느니라"},{"book":"스가랴","ref":"스가랴 4:9","topic":"성전 재건과 성령","text":"스룹바벨의 손이 이 성전의 기초를 놓았은즉 그의 손이 또한 / 그 일을 마치리라 하셨나니 만군의 여호와께서 나를 너희에게 보내신 줄을 네가 알리라 하셨느니라"},{"book":"스가랴","ref":"스가랴 9:9","topic":"메시아 왕의 오심","text":"시온의 딸아 크게 기뻐할지어다 예루살렘의 딸아 즐거이 부를지어다 보라 네 왕이 네게 임하시나니 그는 공의로우시며 구원을 베푸시며 겸손하여서 나귀를 타시나니 나귀의 작은 것 곧 나귀 새끼니라"},{"book":"스가랴","ref":"스가랴 13:7","topic":"목자를 침","text":"만군의 여호와가 말하노라 칼아 깨어서 내 목자, 내 짝 된 자를 치라 목자를 치면 양이 흩어지려니와 작은 자들 위에는 내가 내 손을 드리우리라"},{"book":"말라기","ref":"말라기 3:1","topic":"메시아 오심을 예비","text":"만군의 여호와가 이르노라 보라 내가 내 사자를 보내리니 그가 내 앞에서 길을 준비할 것이요 / 또 너희가 구하는 바 주가 갑자기 그의 성전에 임하시리니 곧 너희가 사모하는 바 언약의 사자가 임하실 것이라"},{"book":"말라기","ref":"말라기 4:2","topic":"여호와의 공의와 치료","text":"내 이름을 경외하는 너희에게는 공의로운 해가 떠올라서 치료하는 광선을 비추리니 너희가 나가서 외양간에서 나온 송아지 같이 뛰리라"},{"book":"말라기","ref":"말라기 4:5","topic":"엘리야를 보냄","text":"보라 여호와의 크고 두려운 날이 이르기 전에 내가 선지자 엘리야를 너희에게 보내리니"},{"book":"창세기","ref":"창세기 1:1","topic":"천지 창조","text":"태초에 하나님이 천지를 창조하시니라"},{"book":"창세기","ref":"창세기 1:2","topic":"천지 창조","text":"땅이 혼돈하고 공허하며 / 흑암이 깊음 위에 있고 하나님의 영은 수면 위에 운행하시니라"},{"book":"창세기","ref":"창세기 1:28","topic":"인간에게 준 축복","text":"하나님이 그들에게 복을 주시며 하나님이 그들에게 이르시되 생육하고 / 번성하여 땅에 충만하라, 땅을 정복하라, 바다의 물고기와 하늘의 새와 땅에 움직이는 모든 생물을 다스리라 하시니라"},{"book":"창세기","ref":"창세기 2:3","topic":"안식일","text":"하나님이 그 일곱째 날을 복되게 하사 거룩하게 하셨으니 이는 하나님이 그 창조하시며 만드시던 모든 일을 마치시고 그 날에 안식하셨음이니라"},{"book":"창세기","ref":"창세기 15:6","topic":"믿음과 의","text":"아브람이 여호와를 믿으니 여호와께서 이를 그의 의로 여기시고"},{"book":"창세기","ref":"창세기 45:7","topic":"하나님의 예비와 섭리","text":"하나님이 큰 구원으로 당신들의 생명을 보존하고 / 당신들의 후손을 세상에 두시려고 나를 당신들보다 먼저 보내셨나니"},{"book":"창세기","ref":"창세기 45:8","topic":"하나님의 예비와 섭리","text":"그런즉 나를 이리로 보낸 이는 당신들이 아니요 하나님이시라 하나님이 나를 바로에게 아버지로 삼으시고 그 온 집의 주로 삼으시며 애굽 온 땅의 통치자로 삼으셨나이다"},{"book":"출애굽기","ref":"출애굽기 3:10","topic":"모세의 사역","text":"이제 내가 너를 바로에게 보내어 너에게 내 백성 이스라엘 자손을 애굽에서 인도하여 내게 하리라"},{"book":"출애굽기","ref":"출애굽기 20:1","topic":"하나님의 구원","text":"하나님이 이 모든 말씀으로 말씀하여 이르시되"},{"book":"출애굽기","ref":"출애굽기 20:2","topic":"하나님의 구원","text":"나는 너를 애굽 땅, 종 되었던 집에서 인도하여 낸 네 하나님 여호와니라"},{"book":"출애굽기","ref":"출애굽기 25:8","topic":"성소의 목적","text":"내가 그들 중에 거할 성소를 그들이 나를 위하여 짓되"},{"book":"출애굽기","ref":"출애굽기 25:9","topic":"성소의 목적","text":"무릇 내가 네게 보이는 모양대로 장막을 짓고 기구들도 그 모양을 따라 지을지니라"},{"book":"출애굽기","ref":"출애굽기 34:6","topic":"하나님의 자비","text":"여호와께서 그의 앞으로 지나시며 선포하시되 여호와라 여호와라 자비롭고 은혜롭고 노하기를 더디하고 / 인자와 진실이 많은 하나님이라"},{"book":"레위기","ref":"레위기 1:2","topic":"레위기 주제","text":"이스라엘 자손에게 말하여 이르라 너희 중에 누구든지 여호와께 예물을 드리려거든 가축 중에서 소나 양으로 예물을 드릴지니라"},{"book":"민수기","ref":"민수기 1:2","topic":"민수기 주제","text":"너희는 이스라엘 자손의 모든 회중 각 남자의 수를 그들의 종족과 조상의 가문에 따라 그 명수대로 계수할지니"},{"book":"민수기","ref":"민수기 10:35","topic":"하나님 중심 공동체","text":"궤가 떠날 때에는 모세가 말하되 / 여호와여 일어나사 주의 대적들을 흩으시고 주를 미워하는 자가 주 앞에서 도망하게 하소서 하였고"},{"book":"민수기","ref":"민수기 10:36","topic":"하나님 중심 공동체","text":"궤가 쉴 때에는 말하되 / 여호와여 이스라엘 종족들에게로 돌아오소서 하였더라"},{"book":"민수기","ref":"민수기 11:29","topic":"성령","text":"모세가 그에게 이르되 네가 나를 두고 시기하느냐 여호와께서 그의 영을 그의 모든 백성에게 주사 다 선지자가 되게 하시기를 원하노라"},{"book":"민수기","ref":"민수기 34:2","topic":"가나안 소유","text":"너는 이스라엘 자손에게 명령하여 그들에게 이르라 너희가 가나안 땅에 들어가는 때에 그 땅은 너희의 기업이 되리니 곧 가나안 사방 지경이라"},{"book":"신명기","ref":"신명기 1:5","topic":"모세의 율법 설명","text":"모세가 요단 저쪽 모압 땅에서 이 율법을 설명하기 시작하였더라 일렀으되"},{"book":"신명기","ref":"신명기 7:6","topic":"선택","text":"너는 여호와 네 하나님의 성민이라 네 하나님 여호와께서 지상 만민 중에서 너를 자기 기업의 백성으로 택하셨나니"},{"book":"신명기","ref":"신명기 7:7","topic":"선택","text":"여호와께서 너희를 기뻐하시고 너희를 택하심은 너희가 다른 민족보다 수효가 많기 때문이 아니니라 너희는 오히려 모든 민족 중에 가장 적으니라"},{"book":"신명기","ref":"신명기 12:11","topic":"예배 장소","text":"너희는 너희의 하나님 여호와께서 자기 이름을 두시려고 택하실 그 곳으로 내가 명령하는 것을 모두 가지고 갈지니 곧 너희의 번제와 너희의 희생과 너희의 십일조와 너희 손의 거제와 너희가 여호와께 서원하는 모든 아름다운 서원물을 가져가고"},{"book":"여호수아","ref":"여호수아 1:2","topic":"여호수아서의 주제","text":"내 종 모세가 죽었으니 이제 너는 이 모든 백성과 더불어 일어나 이 요단을 건너 내가 그들 곧 이스라엘 자손에게 주는 그 땅으로 가라"},{"book":"여호수아","ref":"여호수아 1:7","topic":"순종","text":"오직 강하고 극히 담대하여 나의 종 모세가 네게 명령한 그 율법을 다 지켜 행하고 / 우로나 좌로나 치우치지 말라 그리하면 어디로 가든지 형통하리니"},{"book":"여호수아","ref":"여호수아 5:9","topic":"할례","text":"여호와께서 여호수아에게 이르시되 내가 오늘 애굽의 수치를 너희에게서 떠나가게 하였다 하셨으므로 그 곳 이름을 오늘까지 길갈이라 하느니라"},{"book":"여호수아","ref":"여호수아 13:6하","topic":"땅 분배","text":"내가 그들을 이스라엘 자손 앞에서 쫓아내리니 너는 내가 명령한 대로 그 땅을 이스라엘에게 분배하여 기업이 되게 하되"},{"book":"사사기","ref":"사사기 2:2","topic":"사사기 주제","text":"너희는 이 땅의 주민과 언약을 맺지 말며 그들의 제단들을 헐라 하였거늘 너희가 내 목소리를 듣지 아니하였으니 어찌하여 그리하였느냐"},{"book":"사사기","ref":"사사기 2:3","topic":"사사기 주제","text":"그러므로 내가 또 말하기를 내가 그들을 너희 앞에서 쫓아내지 아니하리니 그들이 너희 옆구리에 가시가 될 것이며 그들의 신들이 너희에게 올무가 되리라 하였노라"},{"book":"사사기","ref":"사사기 8:23","topic":"여호와의 통치","text":"기드온이 그들에게 이르되 내가 너희를 다스리지 아니하겠고 나의 아들도 너희를 다스리지 아니할 것이요 / 여호와께서 너희를 다스리시리라 하니라"},{"book":"사사기","ref":"사사기 13:5","topic":"나실인 삼손","text":"보라 네가 임신하여 아들을 낳으리니 그의 머리 위에 삭도를 대지 말라 이 아이는 태에서 나옴으로부터 하나님께 바쳐진 나실인이 됨이라 그가 블레셋 사람의 손에서 이스라엘을 구원하기 시작하리라 하시니"},{"book":"룻기","ref":"룻기 1:16","topic":"룻기의 주제","text":"룻이 이르되 내게 어머니를 떠나며 어머니를 따르지 말고 돌아가라 강권하지 마옵소서 어머니께서 가시는 곳에 나도 가고 어머니께서 머무시는 곳에서 나도 머물겠나이다 어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니"},{"book":"룻기","ref":"룻기 4:7","topic":"구속자 전통","text":"옛적 이스라엘 중에는 모든 것을 무르거나 교환하는 일을 확정하기 위하여 사람이 그의 신을 벗어 그의 이웃에게 주더니 이것이 이스라엘 중에 증명하는 전례가 된지라"},{"book":"룻기","ref":"룻기 4:15","topic":"회복자 룻","text":"이는 네 생명의 회복자이며 네 노년의 봉양자라 곧 너를 사랑하며 / 일곱 아들보다 귀한 네 며느리가 낳은 자로다 하니라"},{"book":"사무엘상","ref":"사무엘상 2:35","topic":"사무엘서 주제","text":"내가 나를 위하여 충실한 제사장을 일으키리니 그 사람은 내 마음, 내 뜻대로 행할 것이라 내가 그를 위하여 견고한 집을 세우리니 그가 나의 기름 부음을 받은 자 앞에서 영구히 행하리라"},{"book":"사무엘상","ref":"사무엘상 17:47","topic":"여호와의 전쟁과 구원","text":"또 여호와의 구원하심이 칼과 창에 있지 아니함을 이 무리에게 알게 하리라 전쟁은 여호와께 속한 것인즉 / 그가 너희를 우리 손에 넘기시리라"},{"book":"사무엘하","ref":"사무엘하 7:12","topic":"다윗의 후손","text":"네 수한이 차서 네 조상들과 함께 누울 때에 내가 네 몸에서 날 네 씨를 네 뒤에 세워 그의 나라를 견고하게 하리라"},{"book":"사무엘하","ref":"사무엘하 7:13","topic":"다윗의 후손","text":"그는 내 이름을 위하여 집을 건축할 것이요 / 나는 그의 나라 왕위를 영원히 견고하게 하리라"},{"book":"사무엘하","ref":"사무엘하 12:10","topic":"다윗의 범죄","text":"이제 네가 나를 업신여기고 헷 사람 우리아의 아내를 빼앗아 네 아내로 삼았은즉 / 칼이 네 집에서 영원토록 떠나지 아니하리라 하셨고"},{"book":"사무엘하","ref":"사무엘하 24:18","topic":"성전 터","text":"이 날에 갓이 다윗에게 이르러 그에게 아뢰되 올라가서 여부스 사람 아라우나의 타작 마당에서 여호와를 위하여 제단을 쌓으소서 하매"},{"book":"사무엘하","ref":"사무엘하 24:19","topic":"성전 터","text":"다윗이 여호와께서 명령하신 바 갓의 말대로 올라가니라"},{"book":"열왕기상","ref":"열왕기상 5:5","topic":"솔로몬의 성전 건축","text":"여호와께서 내 아버지 다윗에게 하신 말씀에 내가 너를 이어 네 자리에 오르게 할 네 아들 그가 내 이름을 위하여 성전을 건축하리라 하신 대로 내가 내 하나님 여호와의 이름을 위하여 성전을 건축하려 하오니"},{"book":"열왕기상","ref":"열왕기상 13:1","topic":"여로보암의 범죄","text":"보라 그 때에 하나님의 사람이 여호와의 말씀으로 말미암아 유다에서부터 벧엘에 이르니 마침 여로보암이 제단 곁에 서서 분향하는지라"},{"book":"열왕기상","ref":"열왕기상 13:2","topic":"여로보암의 범죄","text":"하나님의 사람이 제단을 향하여 여호와의 말씀으로 외쳐 이르되 제단아 제단아 여호와께서 이와 같이 말씀하시기를 다윗의 집에 요시야라 이름하는 아들을 낳으리니 그가 네 위에 분향하는 산당 제사장을 네 위에서 제물로 바칠 것이요 / 또 사람의 뼈를 네 위에서 사르리라 하셨느니라 하고"},{"book":"열왕기상","ref":"열왕기상 16:30","topic":"아합의 범죄","text":"오므리의 아들 아합이 그의 이전의 모든 사람보다 여호와 보시기에 악을 더욱 행하여"},{"book":"열왕기상","ref":"열왕기상 16:31","topic":"아합의 범죄","text":"느밧의 아들 여로보암의 죄를 따라 행하는 것을 오히려 가볍게 여기며 시돈 사람의 왕 엣바알의 딸 이세벨을 아내로 삼고 가서 바알을 섬겨 예배하고"},{"book":"열왕기상","ref":"열왕기상 19:18","topic":"하나님의 보존","text":"그러나 내가 이스라엘 가운데에 칠천 명을 남기리니 다 바알에게 무릎을 꿇지 아니하고 / 다 바알에게 입맞추지 아니한 자니라"},{"book":"열왕기하","ref":"열왕기하 2:9","topic":"엘리사의 소원","text":"건너매 엘리야가 엘리사에게 이르되 나를 네게서 데려감을 당하기 전에 내가 네게 어떻게 할지를 구하라 엘리사가 이르되 당신의 성령이 하시는 역사가 갑절이나 내게 있게 하소서 하는지라"},{"book":"열왕기하","ref":"열왕기하 9:36","topic":"엘리야의 예언의 성취","text":"예후가 이르되 이는 여호와께서 그 종 디셉 사람 엘리야를 통하여 말씀하신 바라 이르시기를 이스르엘 토지에서 개들이 이세벨의 살을 먹을지라"},{"book":"열왕기하","ref":"열왕기하 17:22","topic":"이스라엘의 범죄","text":"이스라엘 자손이 여로보암이 행한 모든 죄를 따라 행하여 거기서 떠나지 아니하므로"},{"book":"열왕기하","ref":"열왕기하 17:23","topic":"이스라엘의 범죄","text":"여호와께서 그의 종 모든 선지자를 통하여 하신 말씀대로 드디어 이스라엘을 그 앞에서 내쫓으신지라 이스라엘이 고향에서 앗수르에 사로잡혀 가서 오늘까지 이르렀더라"},{"book":"열왕기하","ref":"열왕기하 24:3","topic":"므낫세의 범죄","text":"이 일이 유다에 임함은 곧 여호와의 말씀대로 그들을 자기 앞에서 물리치고자 하심이니 이는 므낫세의 지은 모든 죄 때문이며"},{"book":"열왕기하","ref":"열왕기하 24:4","topic":"므낫세의 범죄","text":"또 그가 무죄한 자의 피를 흘려 그의 피가 예루살렘에 가득하게 하였음이라 여호와께서 사하시기를 즐겨하지 아니하시니라"},{"book":"역대상","ref":"역대상 9:1","topic":"역대상의 주제","text":"온 이스라엘이 그 계보대로 계수되어 그들은 이스라엘 왕조실록에 기록되니라 유다가 범죄함으로 말미암아 바벨론으로 사로잡혀 갔더니"},{"book":"역대상","ref":"역대상 24:3","topic":"제사장 직무 배정","text":"다윗이 엘르아살의 자손 사독과 이다말의 자손 아히멜렉과 더불어 그들을 나누어 각각 그 섬기는 직무를 맡겼는데"},{"book":"역대상","ref":"역대상 24:19","topic":"제사장 직무 배정","text":"이와 같은 직무에 따라 여호와의 성전에 들어가서 그의 아버지 아론을 도왔으니 이는 이스라엘의 하나님 여호와께서 명하신 규례더라"},{"book":"역대상","ref":"역대상 25:1","topic":"레위인 직무 배정","text":"다윗이 군대 지휘관들과 더불어 아삽과 헤만과 여두둔의 자손 중에서 구별하여 섬기게 하되 / 수금과 비파와 제금을 잡아 신령한 노래를 하게 하였으니 그 직무대로 일하는 자의 수효는 이러하니라"},{"book":"역대상","ref":"역대상 29:17","topic":"성전 건축 준비 자세","text":"나의 하나님이여 주께서 마음을 감찰하시고 정직을 기뻐하시는 줄을 내가 아나이다 내가 정직한 마음으로 이 모든 것을 즐거이 드렸사오며 이제 내가 또 여기 있는 주의 백성이 주께 자원하여 드리는 것을 보오니 심히 기쁘도소이다"},{"book":"역대하","ref":"역대하 1:11","topic":"솔로몬의 지혜와 축복","text":"하나님이 솔로몬에게 이르시되 이런 마음이 네게 있어서 부나 재물이나 영광이나 원수의 생명 멸하기를 구하지 아니하며 / 장수도 구하지 아니하고 오직 내가 네게 다스리게 한 내 백성을 재판하기 위하여 지혜와 지식을 구하였으니"},{"book":"역대하","ref":"역대하 1:12","topic":"솔로몬의 지혜와 축복","text":"그러므로 내가 네게 지혜와 지식을 주고 부와 재물과 영광도 주리니 네 전의 왕들도 이런 일이 없었거니와 네 후에도 이런 일이 없으리라 하시니라"},{"book":"역대하","ref":"역대하 2:4","topic":"성전 건축","text":"이제 내가 나의 하나님 여호와의 이름을 위하여 성전을 건축하여 구별하여 드리고 주 앞에서 향 재료를 사르며 항상 떡을 차려 놓으며 안식일과 초하루와 우리 하나님 여호와의 절기에 아침 저녁으로 번제를 드리려 하오니 이는 이스라엘의 영원한 규례니이다"},{"book":"역대하","ref":"역대하 10:19","topic":"이스라엘의 분단","text":"이에 이스라엘이 다윗의 집을 배반하여 오늘날까지 이르니라"},{"book":"역대하","ref":"역대하 13:5","topic":"다윗 언약","text":"이스라엘 하나님 여호와께서 소금 언약으로 이스라엘 나라를 영원히 다윗과 그의 자손에게 주신 것을 너희가 알 것 아니냐"},{"book":"역대하","ref":"역대하 29:5","topic":"성전 개혁","text":"그들에게 이르되 레위 사람들아 내 말을 들으라 이제 너희는 성결하게 하고 / 또 너희 조상들의 하나님 여호와의 전을 성결하게 하여 그 더러운 것을 성소에서 없애라"},{"book":"역대하","ref":"역대하 36:15","topic":"유다의 멸망","text":"그 조상들의 하나님 여호와께서 그의 백성과 그 거하시는 곳을 아끼사 부지런히 그의 사신들을 그 백성에게 보내어 이르셨으나"},{"book":"역대하","ref":"역대하 36:16","topic":"유다의 멸망","text":"그의 백성이 하나님의 사신들을 비웃고 그의 말씀을 멸시하며 / 그의 선지자를 욕하여 여호와의 진노를 그의 백성에게 미치게 하여 회복할 수 없게 하였으므로"},{"book":"역대하","ref":"역대하 36:17","topic":"유다의 멸망","text":"하나님이 갈대아 왕의 손에 그들을 다 넘기시매 그가 와서 그들의 성전에서 칼로 청년들을 죽이며 청년 남녀와 노인과 병약한 사람을 긍휼히 여기지 아니하였으며"},{"book":"에스라","ref":"에스라 3:12","topic":"회복의 감격","text":"제사장들과 레위 사람들과 나이 많은 족장들은 첫 성전을 보았으므로 이제 이 성전의 기초가 놓임을 보고 대성통곡하였으나 여러 사람은 기쁨으로 크게 함성을 지르니"},{"book":"에스라","ref":"에스라 3:13","topic":"회복의 감격","text":"백성이 크게 외치는 소리가 멀리 들리므로 즐거이 부르는 소리와 통곡하는 소리를 백성들이 분간하지 못하였더라"},{"book":"에스라","ref":"에스라 7:12","topic":"에스라와 포로 귀환","text":"모든 왕의 왕 아닥사스다는 하늘의 하나님의 율법에 완전한 학자 겸 제사장 에스라에게"},{"book":"에스라","ref":"에스라 7:13","topic":"에스라와 포로 귀환","text":"조서를 내리노니 우리 나라에 있는 이스라엘 백성과 그들 제사장들과 레위 사람들 중에 예루살렘으로 올라갈 뜻이 있는 자는 누구든지 너와 함께 갈지어다"},{"book":"에스라","ref":"에스라 10:10","topic":"포로 후기 백성의 타락","text":"제사장 에스라가 일어나 그들에게 이르되 너희가 범죄하여 이방 여자를 아내로 삼아 이스라엘의 죄를 더하게 하였으니"},{"book":"에스라","ref":"에스라 10:11","topic":"포로 후기 백성의 타락","text":"이제 너희 조상들의 하나님 앞에서 죄를 자복하고 / 그의 뜻대로 행하여 그 지방 사람들과 이방 여인을 끊어 버리라 하니"},{"book":"느헤미야","ref":"느헤미야 1:5","topic":"언약과 하나님","text":"이르되 하늘의 하나님 여호와 크고 두려우신 하나님이여 주를 사랑하고 / 주의 계명을 지키는 자에게 언약을 지키시며 긍휼을 베푸시는 주여 간구하나이다"},{"book":"느헤미야","ref":"느헤미야 2:5","topic":"포로 귀환과 예루살렘 성벽 재건","text":"왕에게 아뢰되 왕이 만일 좋게 여기시고 종이 왕의 목전에서 은혜를 얻었사오면 나를 유다 땅 나의 조상들의 묘실이 있는 성읍에 보내어 그 성을 건축하게 하옵소서 하였는데"},{"book":"느헤미야","ref":"느헤미야 13:18","topic":"포로 후기 백성의 죄악","text":"너희 조상들이 이같이 행하지 아니하였느냐 그래서 우리 하나님이 이 모든 재앙을 우리와 이 성읍에 내리신 것이 아니냐 그럼에도 불구하고 / 너희가 안식일을 범하여 진노가 이스라엘에게 더욱 심하게 임하도록 하는도다 하고"},{"book":"느헤미야","ref":"느헤미야 13:29","topic":"포로 후기 백성의 죄악","text":"내 하나님이여 그들이 제사장의 직분을 더럽히고 제사장의 직분과 레위 사람에 대한 언약을 어겼사오니 그들을 기억하옵소서"},{"book":"에스더","ref":"에스더 4:16","topic":"하나님 나라를 위한 헌신","text":"당신은 가서 수산에 있는 유다인을 다 모으고 나를 위하여 금식하되 / 밤낮 삼 일을 먹지도 말고 마시지도 마소서 나도 나의 시녀와 더불어 이렇게 금식한 후에 규례를 어기고 왕에게 나아가리니 죽으면 죽으리이다 하니라"},{"book":"에스더","ref":"에스더 9:28","topic":"부림절","text":"각 지방, 각 읍, 각 집에서 대대로 이 두 날을 기념하여 지키되 이 부림일을 유다인 중에서 폐하지 않게 하고 / 그들의 후손들이 계속해서 기념하게 하였더라"},{"book":"욥기","ref":"욥기 1:21","topic":"하나님의 주권","text":"이르되 내가 모태에서 알몸으로 나왔사온즉 또한 / 알몸이 그리로 돌아가올지라 주신 이도 여호와시요 거두신 이도 여호와시오니 여호와의 이름이 찬송을 받으실지니이다 하고"},{"book":"욥기","ref":"욥기 38:4","topic":"창조와 지혜","text":"내가 땅의 기초를 놓을 때에 네가 어디 있었느냐 네가 깨달아 알았거든 말할지니라"},{"book":"욥기","ref":"욥기 38:8","topic":"창조와 지혜","text":"바다가 그 모태에서 터져 나올 때에 문으로 그것을 가둔 자가 누구냐"},{"book":"욥기","ref":"욥기 42:5","topic":"하나님 인식과 회개","text":"내가 주께 대하여 귀로 듣기만 하였사오나 이제는 눈으로 주를 뵈옵나이다"},{"book":"욥기","ref":"욥기 42:6","topic":"하나님 인식과 회개","text":"그러므로 내가 스스로 거두어들이고 티끌과 재 가운데에서 회개하나이다"},{"book":"시편","ref":"시편 1:1","topic":"복 받은 사람","text":"복 있는 사람은 악인들의 꾀를 따르지 아니하며 / 죄인들의 길에 서지 아니하며 오만한 자들의 자리에 앉지 아니하고"},{"book":"시편","ref":"시편 1:2","topic":"복 받은 사람","text":"오직 여호와의 율법을 즐거워하여 그의 율법을 주야로 묵상하는도다"},{"book":"시편","ref":"시편 15:1","topic":"성전에 거할 자","text":"여호와여 주의 장막에 머무를 자 누구오며 주의 성산에 사는 자 누구오니이까"},{"book":"시편","ref":"시편 15:2","topic":"성전에 거할 자","text":"정직하게 행하며 공의를 실천하며 / 그의 마음에 진실을 말하며"},{"book":"시편","ref":"시편 15:3","topic":"성전에 거할 자","text":"그의 혀로 남을 허물하지 아니하고 / 그의 이웃에게 악을 행하지 아니하며 그의 이웃을 비방하지 아니하며"},{"book":"시편","ref":"시편 15:4","topic":"성전에 거할 자","text":"그의 눈은 망령된 자를 멸시하며 여호와를 두려워하는 자들을 존대하며 / 그의 마음에 서원한 것은 해로울지라도 변하지 아니하며"},{"book":"시편","ref":"시편 15:5","topic":"성전에 거할 자","text":"이자를 받으려고 돈을 꾸어 주지 아니하며 / 뇌물을 받고 무죄한 자를 해하지 아니하는 자이니 이런 일을 행하는 자는 영원히 흔들리지 아니하리이다"},{"book":"시편","ref":"시편 19:7","topic":"율법과 삶","text":"여호와의 율법은 완전하여 영혼을 소성시키며 여호와의 증거는 확실하여 우둔한 자를 지혜롭게 하며"},{"book":"시편","ref":"시편 19:8","topic":"율법과 삶","text":"여호와의 교훈은 정직하여 마음을 기쁘게 하고 / 여호와의 계명은 순결하여 눈을 밝게 하시도다"},{"book":"시편","ref":"시편 42:3","topic":"고난과 기도","text":"사람들이 종일 내게 하는 말이 네 하나님이 어디 있느뇨 하오니 내 눈물이 주야로 내 음식이 되었도다"},{"book":"시편","ref":"시편 42:5","topic":"고난과 소망","text":"내 영혼아 네가 어찌하여 낙심하며 / 어찌하여 내 속에서 불안해 하는가 너는 하나님께 소망을 두라 그가 나타나 도우심으로 말미암아 내가 여전히 찬송하리로다"},{"book":"시편","ref":"시편 89:14","topic":"공의의 하나님","text":"의와 공의가 주의 보좌의 기초라 인자함과 진실함이 주 앞에 있나이다"},{"book":"시편","ref":"시편 146:3","topic":"여호와를 의지","text":"귀인들을 의지하지 말며 도울 힘이 없는 인생도 의지하지 말지니"},{"book":"시편","ref":"시편 146:4","topic":"여호와를 의지","text":"그의 호흡이 끊어지면 흙으로 돌아가서 그 날에 그의 생각이 소멸하리로다"},{"book":"시편","ref":"시편 146:5","topic":"여호와를 의지","text":"야곱의 하나님을 자기의 도움으로 삼으며 여호와 자기 하나님에게 자기의 소망을 두는 자는 복이 있도다"},{"book":"잠언","ref":"잠언 11:30","topic":"의인의 열매","text":"의인의 열매는 생명나무라 지혜로운 자는 사람을 얻느니라"},{"book":"잠언","ref":"잠언 16:18","topic":"교만","text":"교만은 패망의 선봉이요 / 거만한 마음은 넘어짐의 앞잡이니라"},{"book":"잠언","ref":"잠언 23:29","topic":"술의 재앙","text":"재앙이 뉘게 있느뇨 근심이 뉘게 있느뇨 분쟁이 뉘게 있느뇨 원망이 뉘게 있느뇨 까닭 없는 상처가 뉘게 있느뇨 붉은 눈이 뉘게 있느뇨"},{"book":"잠언","ref":"잠언 23:30","topic":"술의 재앙","text":"술에 잠긴 자에게 있고 혼합한 술을 구하러 다니는 자에게 있느니라"},{"book":"잠언","ref":"잠언 30:7","topic":"건강한 인생","text":"내가 두 가지 일을 주께 구하였사오니 내가 죽기 전에 내게 거절하지 마시옵소서"},{"book":"잠언","ref":"잠언 30:8","topic":"건강한 인생","text":"곧 헛된 것과 거짓말을 내게서 멀리 하옵시며 나를 가난하게도 마옵시고 부하게도 마옵시고 오직 필요한 양식으로 나를 먹이시옵소서"},{"book":"잠언","ref":"잠언 30:9","topic":"건강한 인생","text":"혹 내가 배불러서 하나님을 모른다 여호와가 누구냐 할까 하오며 혹 내가 가난하여 도둑질하고 / 내 하나님의 이름을 욕되게 할까 두려워함이니이다"},{"book":"전도서","ref":"전도서 1:1","topic":"인생의 헛됨","text":"다윗의 아들 예루살렘 왕 전도자의 말씀이라"},{"book":"전도서","ref":"전도서 1:2","topic":"인생의 헛됨","text":"전도자가 이르되 헛되고 헛되며 헛되고 헛되니 모든 것이 헛되도다"},{"book":"전도서","ref":"전도서 7:14","topic":"헤아릴 수 없는 미래","text":"형통한 날에는 기뻐하고 곤고한 날에는 되돌아보아라 이 두 가지를 하나님이 병행하게 하사 사람이 그의 장래 일을 능히 헤아려 알지 못하게 하셨느니라"},{"book":"전도서","ref":"전도서 11:9","topic":"청년의 때","text":"청년이여 네 어린 때를 즐거워하며 네 청년의 날들을 마음에 기뻐하여 마음에 원하는 길들과 네 눈이 보는 대로 행하라 그러나 하나님이 이 모든 일로 말미암아 너를 심판하실 줄 알라"},{"book":"아가서","ref":"아가서 1:4상","topic":"아가서 주제","text":"왕이 나를 그의 방으로 이끌어 들이시니 / 너는 나를 인도하라 우리가 너를 따라 달려가리라"},{"book":"아가서","ref":"아가서 5:7","topic":"신부의 고난","text":"성 안을 순찰하는 자들이 나를 만나매 나를 쳐서 상하게 하였고 성벽을 파수하는 자들이 나의 겉옷을 벗겨 가졌도다"},{"book":"아가서","ref":"아가서 5:8","topic":"신부의 고난","text":"예루살렘 딸들아 너희에게 내가 부탁한다 너희가 내 사랑하는 자를 만나거든 내가 사랑하므로 병이 났다고 하려무나"},{"book":"아가서","ref":"아가서 8:6","topic":"왕의 사랑","text":"너는 나를 도장 같이 마음에 품고 도장 같이 팔에 두라 사랑은 죽음 같이 강하고 / 질투는 스올 같이 잔인하며 불길 같이 일어나니 그 기세가 여호와의 불과 같으니라"},{"book":"이사야","ref":"이사야 1:3","topic":"이스라엘의 배교","text":"소는 그 임자를 알고 나귀는 그 주인의 구유를 알건마는 이스라엘은 알지 못하고 / 나의 백성은 깨닫지 못하는도다 하셨도다"},{"book":"이사야","ref":"이사야 1:4","topic":"이스라엘의 배교","text":"슬프다 범죄한 나라요 허물 진 백성이요 / 행악의 종자요 행위가 부패한 자식이로다 그들이 여호와를 버리며 이스라엘의 거룩하신 이를 만홀히 여겨 멀리하고 물러갔도다"},{"book":"이사야","ref":"이사야 2:4","topic":"이방의 회복","text":"그가 열방 사이에 판단하시며 많은 백성을 판결하시리니 무리가 그들의 칼을 쳐서 보습을 만들고 그들의 창을 쳐서 낫을 만들 것이며 이 나라와 저 나라가 다시는 칼을 들고 서로 치지 아니하며 다시는 전쟁을 연습하지 아니하리라"},{"book":"이사야","ref":"이사야 11:1","topic":"메시아의 지혜","text":"이새의 줄기에서 한 싹이 나며 그 뿌리에서 한 가지가 나서 결실할 것이요"},{"book":"이사야","ref":"이사야 11:2","topic":"메시아의 지혜","text":"그의 위에 여호와의 영 곧 지혜와 총명의 영이요 / 모략과 재능의 영이요 지식과 여호와를 경외하는 영이 강림하시리니"},{"book":"이사야","ref":"이사야 43:1","topic":"이스라엘의 회복","text":"야곱아 너를 창조하신 여호와께서 지금 말씀하시느니라 이스라엘아 너를 지으신 이가 말씀하시느니라 너는 두려워하지 말라 내가 너를 구속하였고 내가 너를 지명하여 불렀나니 너는 내 것이라"},{"book":"이사야","ref":"이사야 43:21","topic":"하나님 백성의 목적","text":"이 백성은 내가 나를 위하여 지었나니 나를 찬송하게 하려 함이니라"},{"book":"이사야","ref":"이사야 53:1","topic":"메시아의 고난","text":"우리가 전한 것을 누가 믿었느냐 여호와의 팔이 누구에게 나타났느냐"},{"book":"이사야","ref":"이사야 53:2","topic":"메시아의 고난","text":"그는 주 앞에서 자라나기를 연한 순 같고 마른 땅에서 나온 뿌리 같아서 고운 모양도 없고 풍채도 없은즉 / 우리가 보기에 흠모할 만한 아름다운 것이 없도다"},{"book":"이사야","ref":"이사야 55:1","topic":"하나님이 부르심","text":"오호라 너희 모든 목마른 자들아 물로 나아오라 돈 없는 자도 오라 너희는 와서 사 먹되 돈 없이, 값 없이 와서 포도주와 젖을 사라"},{"book":"이사야","ref":"이사야 55:2","topic":"하나님이 부르심","text":"너희가 어찌하여 양식이 아닌 것을 위하여 은을 달아 주며 배부르게 하지 못할 것을 위하여 수고하느냐 내게 듣고 들을지어다 그리하면 너희가 좋은 것을 먹을 것이며 너희 자신들이 기름진 것으로 즐거움을 얻으리라"},{"book":"예레미야","ref":"예레미야 29:11","topic":"하나님이 들으시는 기도","text":"여호와의 말씀이니라 너희를 향한 나의 생각을 내가 아나니 평안이요 / 재앙이 아니니라 너희에게 미래와 희망을 주는 것이니라"},{"book":"예레미야","ref":"예레미야 29:12","topic":"하나님이 들으시는 기도","text":"너희가 내게 부르짖으며 내게 와서 기도하면 내가 너희들의 기도를 들을 것이요"},{"book":"예레미야","ref":"예레미야 29:13","topic":"하나님이 들으시는 기도","text":"너희가 온 마음으로 나를 구하면 나를 찾을 것이요 / 나를 만나리라"},{"book":"예레미야","ref":"예레미야 33:3","topic":"기도 응답","text":"너는 내게 부르짖으라 내가 네게 응답하겠고 네가 알지 못하는 크고 은밀한 일을 네게 보이리라"},{"book":"예레미야","ref":"예레미야 5:21","topic":"회복을 위한 기도","text":"여호와여 우리를 주께로 돌이키소서 그리하시면 우리가 주께로 돌아가겠사오니 우리의 날들을 다시 새롭게 하사 옛적 같게 하옵소서"},{"book":"에스겔","ref":"에스겔 4:1","topic":"선지자의 소명","text":"너 인자야 토판을 가져다가 그것을 네 앞에 놓고 한 성읍 곧 예루살렘을 그 위에 그리고"},{"book":"에스겔","ref":"에스겔 4:3","topic":"선지자의 소명","text":"또 철판을 가져다가 너와 성읍 사이에 두어 철벽을 삼고 성을 포위하는 것처럼 에워싸라 이것이 이스라엘 족속에게 징조가 되리라"},{"book":"에스겔","ref":"에스겔 18:2","topic":"죄와 징벌","text":"너희가 이스라엘 땅에 관한 속담에 이르기를 아버지가 신 포도를 먹었으므로 그의 아들의 이가 시다고 함은 어찌 됨이냐"},{"book":"에스겔","ref":"에스겔 18:4","topic":"모든 영혼은 하나님 소유","text":"모든 영혼이 다 내게 속한지라 아버지의 영혼이 내게 속함 같이 그의 아들의 영혼도 내게 속하였나니 범죄하는 그 영혼은 죽으리라"},{"book":"에스겔","ref":"에스겔 43:4","topic":"하나님 영광이 돌아옴","text":"여호와의 영광이 동문을 통하여 성전으로 들어가고"},{"book":"에스겔","ref":"에스겔 43:5","topic":"하나님 영광이 돌아옴","text":"영이 나를 들어 데리고 안뜰에 들어가시기로 내가 보니 여호와의 영광이 성전에 가득하더라"},{"book":"다니엘","ref":"다니엘 3:17","topic":"성도의 인내","text":"왕이여 우리가 섬기는 하나님이 계시다면 우리를 맹렬히 타는 풀무불 가운데에서 능히 건져내시겠고 왕의 손에서도 건져 내시리이다"},{"book":"다니엘","ref":"다니엘 3:18","topic":"성도의 인내","text":"그렇게 하지 아니하실지라도 왕이여 우리가 왕의 신들을 섬기지도 아니하고 / 왕이 세우신 금 신상에게 절하지도 아니할 줄을 아옵소서"},{"book":"호세아","ref":"호세아 1:2","topic":"호세아의 주제","text":"여호와께서 처음 호세아에게 말씀하실 때 여호와께서 호세아에게 이르시되 너는 가서 음란한 여자를 맞이하여 음란한 자식들을 낳으라 이 나라가 여호와를 떠나 크게 음란함이니라 하시니"},{"book":"호세아","ref":"호세아 6:3","topic":"여호와를 알자","text":"그러므로 우리가 여호와를 알자 힘써 여호와를 알자 그의 나타나심은 새벽 빛 같이 어김없나니 비와 같이, 땅을 적시는 늦은 비와 같이 우리에게 임하시리라 하니라"},{"book":"호세아","ref":"호세아 11:1","topic":"애굽에서 구원","text":"이스라엘이 어렸을 때에 내가 사랑하여 내 아들을 애굽에서 불러냈거늘"},{"book":"호세아","ref":"호세아 14:9","topic":"여호와의 도","text":"누가 지혜가 있어 이런 일을 깨달으며 누가 총명이 있어 이런 일을 알겠느냐 여호와의 도는 정직하니 / 의인은 그 길로 다니거니와 그러나 죄인은 그 길에 걸려 넘어지리라"},{"book":"요엘","ref":"요엘 1:15","topic":"여호와의 날","text":"슬프다 그 날이여 여호와의 날이 가까웠나니 곧 멸망 같이 전능자에게로부터 이르리로다"},{"book":"요엘","ref":"요엘 2:13","topic":"진정한 회개","text":"너희는 옷을 찢지 말고 마음을 찢고 너희 하나님 여호와께로 돌아올지어다 그는 은혜로우시며 자비로우시며 노하기를 더디 하시며 인애가 크시사 뜻을 돌이켜 재앙을 내리지 아니하시나니"},{"book":"아모스","ref":"아모스 2:6","topic":"이스라엘의 죄","text":"여호와께서 이와 같이 말씀하시되 이스라엘의 서너 가지 죄로 말미암아 내가 그 벌을 돌이키지 아니하리니 이는 그들이 은을 받고 의인을 팔며 신 한 켤레를 받고 가난한 자를 팔며"},{"book":"아모스","ref":"아모스 2:7","topic":"이스라엘의 죄","text":"힘없는 자의 머리를 티끌 먼지 속에 발로 밟고 연약한 자의 길을 굽게 하며 / 아버지와 아들이 한 젊은 여인에게 다녀서 내 거룩한 이름을 더럽히며"},{"book":"아모스","ref":"아모스 2:8","topic":"이스라엘의 죄","text":"모든 제단 옆에서 전당 잡은 옷 위에 누우며 그들의 신전에서 벌금으로 얻은 포도주를 마심이니라"},{"book":"아모스","ref":"아모스 3:2","topic":"죄와 징벌","text":"내가 땅의 모든 족속 가운데 너희만을 알았나니 그러므로 내가 너희 모든 죄악을 너희에게 보응하리라 하셨나니"},{"book":"아모스","ref":"아모스 5:15","topic":"선행하는 자를 구원","text":"너희는 악을 미워하고 선을 사랑하며 / 성문에서 정의를 세울지어다 만군의 하나님 여호와께서 혹시 요셉의 남은 자를 불쌍히 여기시리라"},{"book":"아모스","ref":"아모스 7:14","topic":"아모스의 소명","text":"아모스가 아마샤에게 대답하여 이르되 나는 선지자가 아니며 선지자의 아들도 아니라 나는 목자요 뽕나무를 재배하는 자로서"},{"book":"아모스","ref":"아모스 7:15","topic":"아모스의 소명","text":"양 떼를 따를 때에 여호와께서 나를 데려다가 여호와께서 내게 이르시기를 가서 내 백성 이스라엘에게 예언하라 하셨나니"},{"book":"오바댜","ref":"오바댜 1:1상","topic":"오바댜의 주제","text":"오바댜의 묵시라 주 여호와께서 에돔에 대하여 이와 같이 말씀하시니라"},{"book":"오바댜","ref":"오바댜 1:3","topic":"교만한 에돔 사람","text":"너의 마음의 교만이 너를 속였도다 바위틈에 거주하며 / 높은 곳에 사는 자여 네가 마음에 이르기를 누가 능히 나를 땅에 끌어내리겠느냐 하니"},{"book":"오바댜","ref":"오바댜 1:4","topic":"교만한 에돔 사람","text":"네가 독수리처럼 높이 오르며 별 사이에 깃들일지라도 내가 거기에서 너를 끌어내리리라 여호와의 말씀이니라"},{"book":"요나","ref":"요나 1:2","topic":"요나의 불순종","text":"너는 일어나 저 큰 성읍 니느웨로 가서 그것을 향하여 외치라 그 악독이 내 앞에 상달되었음이니라 하시니라"},{"book":"요나","ref":"요나 1:3","topic":"요나의 불순종","text":"그러나 요나가 여호와의 얼굴을 피하려고 일어나 다시스로 도망하려 하여 욥바로 내려갔더니"},{"book":"요나","ref":"요나 1:6","topic":"요나와 이방인","text":"선장이 그에게 가서 이르되 자는 자여 어찌함이냐 일어나서 네 하나님께 구하라 혹시 하나님이 우리를 생각하사 망하지 아니하게 하시리라 하니라"},{"book":"미가","ref":"미가 3:1","topic":"지도자들의 학정","text":"내가 또 이르노니 야곱의 우두머리들과 이스라엘 족속의 통치자들아 들으라 정의를 아는 것이 너희의 본분이 아니냐"},{"book":"미가","ref":"미가 3:2","topic":"지도자들의 학정","text":"너희가 선을 미워하고 / 악을 기뻐하여 내 백성의 가죽을 벗기고 그 뼈에서 살을 뜯어"},{"book":"미가","ref":"미가 3:3","topic":"지도자들의 학정","text":"그들의 살을 먹으며 그 가죽을 벗기며 그 뼈를 꺾어 다지기를 냄비와 솥 가운데에 담을 고기처럼 하는도다"},{"book":"미가","ref":"미가 3:8","topic":"선지자의 삶","text":"오직 나는 여호와의 영으로 말미암아 능력과 정의와 용기로 충만해져서 야곱의 허물과 이스라엘의 죄를 그들에게 보이리라"},{"book":"미가","ref":"미가 4:3","topic":"이방인의 구원","text":"그가 많은 민족들 사이의 일을 심판하시며 먼 곳 강한 이방 사람을 판결하시리니 무리가 그 칼을 쳐서 보습을 만들고 창을 쳐서 낫을 만들 것이며 이 나라와 저 나라가 다시는 칼을 들고 서로 치지 아니하며 다시는 전쟁을 연습하지 아니하고"},{"book":"미가","ref":"미가 4:4","topic":"이방인의 구원","text":"각 사람이 자기 포도나무 아래와 자기 무화과나무 아래에 앉을 것이라 그들을 두렵게 할 자가 없으리니 이는 만군의 여호와의 입이 이같이 말씀하셨음이라"},{"book":"미가","ref":"미가 6:6","topic":"하나님이 원하는 것","text":"내가 무엇을 가지고 여호와 앞에 나아가며 높으신 하나님께 경배할까 내가 번제물로 일 년 된 송아지를 가지고 그 앞에 나아갈까"},{"book":"미가","ref":"미가 7:6","topic":"종말과 가족 갈등","text":"아들이 아버지를 멸시하며 딸이 어머니를 대적하며 / 며느리가 시어머니를 대적하리니 사람의 원수가 곧 자기의 집안사람이리로다"},{"book":"나훔","ref":"나훔 1:1","topic":"나훔의 주제","text":"니느웨에 대한 경고 곧 엘고스 사람 나훔의 묵시의 글이라"},{"book":"하박국","ref":"하박국 1:2","topic":"하박국의 부르짖음","text":"여호와여 내가 부르짖어도 주께서 듣지 아니하시니 / 어느 때까지리이까 내가 강포로 말미암아 외쳐도 주께서 구원하지 아니하시나이다"},{"book":"하박국","ref":"하박국 1:3","topic":"하박국의 부르짖음","text":"어찌하여 내게 죄악을 보게 하시며 패역을 눈으로 보게 하시나이까 겁탈과 강포가 내 앞에 있고 변론과 분쟁이 일어났나이다"},{"book":"하박국","ref":"하박국 1:4","topic":"하박국의 부르짖음","text":"이러므로 율법이 해이하고 / 정의가 전혀 시행되지 못하오니 이는 악인이 의인을 에워쌌으므로 정의가 굽게 행하여짐이니이다"},{"book":"하박국","ref":"하박국 3:17","topic":"하나님과 동행함의 기쁨","text":"비록 무화과나무가 무성하지 못하며 / 포도나무에 열매가 없으며 감람나무에 소출이 없으며 밭에 먹을 것이 없으며 우리에 양이 없으며 외양간에 소가 없을지라도"},{"book":"하박국","ref":"하박국 3:18","topic":"하나님과 동행함의 기쁨","text":"나는 여호와로 말미암아 즐거워하며 / 나의 구원의 하나님으로 말미암아 기뻐하리로다"},{"book":"하박국","ref":"하박국 3:19","topic":"하나님과 동행함의 기쁨","text":"주 여호와는 나의 힘이시라 나의 발을 사슴과 같게 하사 나를 나의 높은 곳으로 다니게 하시리로다 이 노래는 지휘하는 사람을 위하여 내 수금에 맞춘 것이니라"},{"book":"스바냐","ref":"스바냐 1:14","topic":"여호와의 진노의 날","text":"여호와의 큰 날이 가깝도다 가깝고도 빠르도다 여호와의 날의 소리로다 용사가 거기서 심히 슬피 우는도다"},{"book":"스바냐","ref":"스바냐 1:15","topic":"여호와의 진노의 날","text":"그날은 분노의 날이요 환난과 고통의 날이요 / 황폐와 패망의 날이요 캄캄하고 어두운 날이요 구름과 흑암의 날이요"},{"book":"스바냐","ref":"스바냐 1:16","topic":"여호와의 진노의 날","text":"나팔을 불어 경고하며 / 견고한 성읍들을 치며 높은 망대를 치는 날이로다"},{"book":"학개","ref":"학개 1:4","topic":"학개의 주제","text":"이 성전이 황폐하였거늘 너희가 이때에 판벽한 집에 거주하는 것이 옳으냐"},{"book":"학개","ref":"학개 1:14","topic":"성전 재건과 성령","text":"여호와께서 스알디엘의 아들 유다 총독 스룹바벨의 마음과 여호사닥의 아들 대제사장 여호수아의 마음과 남은 모든 백성의 마음을 감동시키시매 그들이 와서 만군의 여호와 그들의 하나님의 전 공사를 하였으니"},{"book":"스가랴","ref":"스가랴 1:15","topic":"예루살렘의 회복","text":"안일한 여러 나라들 때문에 심히 진노하나니 나는 조금 노하였거늘 그들은 힘을 내어 고난을 더하였음이라"},{"book":"스가랴","ref":"스가랴 1:16","topic":"예루살렘의 회복","text":"그러므로 여호와가 이처럼 말하노라 내가 불쌍히 여기므로 예루살렘에 돌아왔은즉 / 내 집이 그 가운데에 건축되리니 예루살렘 위에 먹줄이 쳐지리라 만군의 여호와의 말이니라"},{"book":"스가랴","ref":"스가랴 14:16","topic":"이방인의 회복","text":"예루살렘을 치러 왔던 이방 나라들 중에 남은 자가 해마다 올라와서 그 왕 만군의 여호와께 경배하며 / 초막절을 지킬 것이라"},{"book":"말라기","ref":"말라기 1:6","topic":"제사장들의 타락","text":"내 이름을 멸시하는 제사장들아 나 만군의 여호와가 너희에게 이르기를 아들은 그 아버지를, 종은 그 주인을 공경하나니 내가 아버지일진대 나를 공경함이 어디 있느냐 내가 주인일진대 나를 두려워함이 어디 있느냐 하나 너희는 이르기를 우리가 어떻게 주의 이름을 멸시하였나이까 하는도다"},{"book":"말라기","ref":"말라기 2:15","topic":"가정과 경건한 자손","text":"그에게는 영이 충만하였으나 오직 하나를 만들지 아니하셨느냐 어찌하여 하나만 만드셨느냐 이는 경건한 자손을 얻고자 하심이라 그러므로 네 심령을 삼가 지켜 어려서 맞이한 아내에게 거짓을 행하지 말지니라"}];
var NT_VERSES = [{"book":"마태복음","ref":"마태복음 1:21","topic":"예수의 뜻","text":"아들을 낳으리니 이름을 예수라 하라 이는 그가 자기 백성을 그들의 죄에서 구원할 자이심이라 하니라"},{"book":"마태복음","ref":"마태복음 1:23","topic":"그리스도의 동정녀 탄생","text":"보라 처녀가 잉태하여 아들을 낳을 것이요 / 그의 이름은 임마누엘이라 하리라 하셨으니 이를 번역한즉 하나님이 우리와 함께 계시다 함이라"},{"book":"마태복음","ref":"마태복음 5:3","topic":"팔복","text":"심령이 가난한 자는 복이 있나니 천국이 그들의 것임이요"},{"book":"마태복음","ref":"마태복음 5:4","topic":"팔복","text":"애통하는 자는 복이 있나니 그들이 위로를 받을 것임이요"},{"book":"마태복음","ref":"마태복음 5:5","topic":"팔복","text":"온유한 자는 복이 있나니 그들이 땅을 기업으로 받을 것임이요"},{"book":"마태복음","ref":"마태복음 5:16","topic":"천국 백성의 선행","text":"이같이 너희 빛이 사람 앞에 비치게 하여 그들로 너희 착한 행실을 보고 하늘에 계신 너희 아버지께 영광을 돌리게 하라"},{"book":"마태복음","ref":"마태복음 5:44","topic":"원수 사랑","text":"나는 너희에게 이르노니 너희 원수를 사랑하며 / 너희를 박해하는 자를 위하여 기도하라"},{"book":"마태복음","ref":"마태복음 5:45","topic":"원수 사랑","text":"이같이 한즉 하늘에 계신 너희 아버지의 아들이 되리니 이는 하나님이 그 해를 악인과 선인에게 비추시며 비를 의로운 자와 불의한 자에게 내려주심이라"},{"book":"마태복음","ref":"마태복음 6:3","topic":"은밀한 구제","text":"너는 구제할 때에 오른손이 하는 것을 왼손이 모르게 하여"},{"book":"마태복음","ref":"마태복음 6:4","topic":"은밀한 구제","text":"네 구제함을 은밀하게 하라 은밀한 중에 보시는 너의 아버지께서 갚으시리라"},{"book":"마태복음","ref":"마태복음 6:33","topic":"먼저 구할 것","text":"그런즉 너희는 먼저 그의 나라와 그의 의를 구하라 그리하면 이 모든 것을 너희에게 더하시리라"},{"book":"마태복음","ref":"마태복음 7:12","topic":"황금률","text":"그러므로 무엇이든지 남에게 대접을 받고자 하는 대로 너희도 남을 대접하라 이것이 율법이요 선지자니라"},{"book":"마태복음","ref":"마태복음 16:16","topic":"베드로의 신앙고백","text":"시몬 베드로가 대답하여 이르되 주는 그리스도시요 살아 계신 하나님의 아들이시니이다"},{"book":"마태복음","ref":"마태복음 28:18","topic":"지상명령. 세례와 삼위일체","text":"예수께서 나아와 말씀하여 이르시되 하늘과 땅의 모든 권세를 내게 주셨으니"},{"book":"마태복음","ref":"마태복음 28:19","topic":"지상명령. 세례와 삼위일체","text":"그러므로 너희는 가서 모든 민족을 제자로 삼아 아버지와 아들과 성령의 이름으로 세례를 베풀고"},{"book":"마태복음","ref":"마태복음 28:20","topic":"지상명령. 세례와 삼위일체","text":"내가 너희에게 분부한 모든 것을 가르쳐 지키게 하라 볼지어다 내가 세상 끝날까지 너희와 항상 함께 있으리라 하시니라"},{"book":"마가복음","ref":"마가복음 8:35","topic":"순교 신앙","text":"누구든지 자기 목숨을 구원하고자 하면 잃을 것이요 / 누구든지 나와 복음을 위하여 자기 목숨을 잃으면 구원하리라"},{"book":"마가복음","ref":"마가복음 10:45","topic":"인자의 온 목적","text":"인자가 온 것은 섬김을 받으려 함이 아니라 도리어 섬기려 하고 / 자기 목숨을 많은 사람의 대속물로 주려 함이니라"},{"book":"요한복음","ref":"요한복음 1:12","topic":"하나님의 자녀 되는 권세","text":"영접하는 자 곧 그 이름을 믿는 자들에게는 하나님의 자녀가 되는 권세를 주셨으니"},{"book":"요한복음","ref":"요한복음 1:13","topic":"하나님의 자녀 되는 권세","text":"이는 혈통으로나 육정으로나 사람의 뜻으로 나지 아니하고 / 오직 하나님께로부터 난 자들이니라"},{"book":"요한복음","ref":"요한복음 1:14","topic":"성육신","text":"말씀이 육신이 되어 우리 가운데 거하시매 우리가 그의 영광을 보니 아버지의 독생자의 영광이요 / 은혜와 진리가 충만하더라"},{"book":"요한복음","ref":"요한복음 3:5","topic":"중생","text":"예수께서 대답하시되 진실로 진실로 네게 이르노니 사람이 물과 성령으로 나지 아니하면 하나님의 나라에 들어갈 수 없느니라"},{"book":"요한복음","ref":"요한복음 3:16","topic":"하나님의 사랑","text":"하나님이 세상을 이처럼 사랑하사 독생자를 주셨으니 이는 그를 믿는 자마다 멸망하지 않고 영생을 얻게 하려 하심이라"},{"book":"요한복음","ref":"요한복음 5:24","topic":"영생을 얻음","text":"내가 진실로 진실로 너희에게 이르노니 내 말을 듣고 또 나 보내신 이를 믿는 자는 영생을 얻었고 심판에 이르지 아니하나니 사망에서 생명으로 옮겼느니라"},{"book":"요한복음","ref":"요한복음 6:35","topic":"생명의 떡","text":"예수께서 이르시되 나는 생명의 떡이니 내게 오는 자는 결코 주리지 아니할 터이요 / 나를 믿는 자는 영원히 목마르지 아니하리라"},{"book":"요한복음","ref":"요한복음 11:25","topic":"부활과 생명 되신 예수님","text":"예수께서 이르시되 나는 부활이요 / 생명이니 나를 믿는 자는 죽어도 살겠고"},{"book":"요한복음","ref":"요한복음 11:26","topic":"부활과 생명 되신 예수님","text":"무릇 살아서 나를 믿는 자는 영원히 죽지 아니하리니 이것을 네가 믿느냐"},{"book":"요한복음","ref":"요한복음 14:6","topic":"그리스도의 유일성","text":"예수께서 이르시되 내가 곧 길이요 / 진리요 생명이니 나로 말미암지 않고는 아버지께로 올 자가 없느니라"},{"book":"요한복음","ref":"요한복음 17:3","topic":"영생의 정의","text":"영생은 곧 유일하신 참 하나님과 그가 보내신 자 예수 그리스도를 아는 것이니이다"},{"book":"요한복음","ref":"요한복음 20:31","topic":"요한복음을 기록한 목적","text":"오직 이것을 기록함은 너희로 예수께서 하나님의 아들 그리스도이심을 믿게 하려 함이요 / 또 너희로 믿고 그 이름을 힘입어 생명을 얻게 하려 함이니라"},{"book":"사도행전","ref":"사도행전 1:8","topic":"성령과 복음 전파","text":"오직 성령이 너희에게 임하시면 너희가 권능을 받고 예루살렘과 온 유대와 사마리아와 땅 끝까지 이르러 내 증인이 되리라 하시니라"},{"book":"사도행전","ref":"사도행전 4:12","topic":"그리스도의 유일성","text":"다른 이로써는 구원을 받을 수 없나니 천하 사람 중에 구원을 받을 만한 다른 이름을 우리에게 주신 일이 없음이라 하였더라"},{"book":"사도행전","ref":"사도행전 20:24","topic":"사도 바울의 사명 의식","text":"내가 달려갈 길과 주 예수께 받은 사명 곧 하나님의 은혜의 복음을 증언하는 일을 마치려 함에는 나의 생명조차 조금도 귀한 것으로 여기지 아니하노라"},{"book":"로마서","ref":"로마서 1:16","topic":"하나님의 능력 된 복음","text":"내가 복음을 부끄러워하지 아니하노니 이 복음은 모든 믿는 자에게 구원을 주시는 하나님의 능력이 됨이라 먼저는 유대인에게요 그리고 헬라인에게로다"},{"book":"로마서","ref":"로마서 3:23","topic":"그리스도 예수 안에 있는 속량","text":"모든 사람이 죄를 범하였으매 하나님의 영광에 이르지 못하더니"},{"book":"로마서","ref":"로마서 3:24","topic":"그리스도 예수 안에 있는 속량","text":"그리스도 예수 안에 있는 속량으로 말미암아 하나님의 은혜로 값없이 의롭다 하심을 얻은 자 되었느니라"},{"book":"로마서","ref":"로마서 5:1","topic":"이신칭의의 결과","text":"그러므로 우리가 믿음으로 의롭다 하심을 받았으니 우리 주 예수 그리스도로 말미암아 하나님과 화평을 누리자"},{"book":"로마서","ref":"로마서 5:8","topic":"하나님의 사랑 확증","text":"우리가 아직 죄인 되었을 때에 그리스도께서 우리를 위하여 죽으심으로 하나님께서 우리에 대한 자기의 사랑을 확증하셨느니라"},{"book":"로마서","ref":"로마서 6:13","topic":"의의 무기","text":"또한 너희 지체를 불의의 무기로 죄에게 내주지 말고 오직 너희 자신을 죽은 자 가운데서 다시 살아난 자 같이 하나님께 드리며 너희 지체를 의의 무기로 하나님께 드리라"},{"book":"로마서","ref":"로마서 8:1","topic":"정죄함이 없음","text":"그러므로 이제 그리스도 예수 안에 있는 자에게는 결코 정죄함이 없나니"},{"book":"로마서","ref":"로마서 8:2","topic":"정죄함이 없음","text":"이는 그리스도 예수 안에 있는 생명의 성령의 법이 죄와 사망의 법에서 너를 해방하였음이라"},{"book":"로마서","ref":"로마서 8:15","topic":"양자의 영","text":"너희는 다시 무서워하는 종의 영을 받지 아니하고 / 양자의 영을 받았으므로 우리가 아빠 아버지라고 부르짖느니라"},{"book":"로마서","ref":"로마서 10:9","topic":"구원에 이르는 믿음","text":"네가 만일 네 입으로 예수를 주로 시인하며 / 또 하나님께서 그를 죽은 자 가운데서 살리신 것을 네 마음에 믿으면 구원을 받으리라"},{"book":"로마서","ref":"로마서 10:10","topic":"구원에 이르는 믿음","text":"사람이 마음으로 믿어 의에 이르고 입으로 시인하여 구원에 이르느니라"},{"book":"로마서","ref":"로마서 11:36","topic":"하나님께 영광","text":"이는 만물이 주에게서 나오고 주로 말미암고 주에게로 돌아감이라 그에게 영광이 세세에 있을지어다 아멘"},{"book":"로마서","ref":"로마서 12:1","topic":"거룩한 산 제물","text":"그러므로 형제들아 내가 하나님의 모든 자비하심으로 너희를 권하노니 너희 몸을 하나님이 기뻐하시는 거룩한 산 제물로 드리라 이는 너희가 드릴 영적 예배니라"},{"book":"로마서","ref":"로마서 14:8","topic":"주를 위하여 살고 죽음","text":"우리가 살아도 주를 위하여 살고 죽어도 주를 위하여 죽나니 그러므로 사나 죽으나 우리가 주의 것이로다"},{"book":"로마서","ref":"로마서 14:17","topic":"하나님 나라의 성격","text":"하나님의 나라는 먹는 것과 마시는 것이 아니요 오직 성령 안에 있는 의와 평강과 희락이라"},{"book":"고린도전서","ref":"고린도전서 6:19","topic":"우리 몸은 성령의 전","text":"너희 몸은 너희가 하나님께로부터 받은 바 너희 가운데 계신 성령의 전인 줄을 알지 못하느냐 너희는 너희 자신의 것이 아니라"},{"book":"고린도전서","ref":"고린도전서 6:20","topic":"우리 몸은 성령의 전","text":"값으로 산 것이 되었으니 그런즉 / 너희 몸으로 하나님께 영광을 돌리라"},{"book":"고린도전서","ref":"고린도전서 10:31","topic":"하나님의 영광을 위하여 하라","text":"그런즉 너희가 먹든지 마시든지 무엇을 하든지 다 하나님의 영광을 위하여 하라"},{"book":"고린도전서","ref":"고린도전서 12:3","topic":"하나님의 영으로 말하는 자","text":"그러므로 내가 너희에게 알리노니 하나님의 영으로 말하는 자는 누구든지 예수를 저주할 자라 하지 아니하고 / 또 성령으로 아니하고는 누구든지 예수를 주시라 할 수 없느니라"},{"book":"고린도후서","ref":"고린도후서 4:5","topic":"우리의 전파하는 것","text":"우리는 우리를 전파하는 것이 아니라 오직 그리스도 예수의 주 되신 것과 또 예수를 위하여 우리가 너희의 종 된 것을 전파함이라"},{"book":"고린도후서","ref":"고린도후서 5:15","topic":"대속의 목적","text":"그가 모든 사람을 대신하여 죽으심은 살아 있는 자들로 하여금 다시는 그들 자신을 위하여 살지 않고 오직 그들을 대신하여 죽었다가 다시 살아나신 이를 위하여 살게 하려 함이라"},{"book":"고린도후서","ref":"고린도후서 5:17","topic":"새로운 피조물","text":"그런즉 누구든지 그리스도 안에 있으면 새로운 피조물이라 이전 것은 지나갔으니 보라 새 것이 되었도다"},{"book":"고린도후서","ref":"고린도후서 7:1","topic":"거룩함을 이룸","text":"그런즉 사랑하는 자들아 이 약속을 가진 우리는 하나님을 두려워하는 가운데서 거룩함을 온전히 이루어 육과 영의 온갖 더러운 것에서 자신을 깨끗하게 하자"},{"book":"고린도후서","ref":"고린도후서 13:5","topic":"구원의 확신","text":"너희는 믿음 안에 있는가 너희 자신을 시험하고 / 너희 자신을 확증하라 예수 그리스도께서 너희 안에 계신 줄을 너희가 스스로 알지 못하느냐 그렇지 않으면 너희는 버림 받은 자니라"},{"book":"고린도후서","ref":"고린도후서 13:13","topic":"축도","text":"주 예수 그리스도의 은혜와 하나님의 사랑과 성령의 교통하심이 너희 무리와 함께 있을지어다"},{"book":"갈라디아서","ref":"갈라디아서 2:16","topic":"이신칭의","text":"사람이 의롭게 되는 것은 율법의 행위로 말미암음이 아니요 오직 예수 그리스도를 믿음으로 말미암는 줄 알므로 우리도 그리스도 예수를 믿나니 이는 우리가 율법의 행위로써가 아니고 그리스도를 믿음으로써 의롭다 함을 얻으려 함이라 율법의 행위로써는 의롭다 함을 얻을 육체가 없느니라"},{"book":"갈라디아서","ref":"갈라디아서 2:20","topic":"내 안에 그리스도께 사심","text":"내가 그리스도와 함께 십자가에 못 박혔나니 그런즉 / 이제는 내가 사는 것이 아니요 오직 내 안에 그리스도께서 사시는 것이라 이제 내가 육체 가운데 사는 것은 나를 사랑하사 나를 위하여 자기 자신을 버리신 하나님의 아들을 믿는 믿음 안에서 사는 것이라"},{"book":"갈라디아서","ref":"갈라디아서 3:28","topic":"그리스도 안에서 하나","text":"너희는 유대인이나 헬라인이나 종이나 자유인이나 남자나 여자나 다 그리스도 예수 안에서 하나이니라"},{"book":"갈라디아서","ref":"갈라디아서 5:22","topic":"성령의 열매","text":"오직 성령의 열매는 사랑과 희락과 화평과 오래 참음과 자비와 양선과 충성과"},{"book":"갈라디아서","ref":"갈라디아서 5:23","topic":"성령의 열매","text":"온유와 절제니 이같은 것을 금지할 법이 없느니라"},{"book":"갈라디아서","ref":"갈라디아서 6:14","topic":"우리의 자랑할 것","text":"그러나 내게는 우리 주 예수 그리스도의 십자가 외에 결코 자랑할 것이 없으니 그리스도로 말미암아 세상이 나를 대하여 십자가에 못 박히고 내가 또한 세상을 대하여 그러하니라"},{"book":"에베소서","ref":"에베소서 2:8","topic":"은혜로 인한 구원","text":"너희는 그 은혜에 의하여 믿음으로 말미암아 구원을 받았으니 이것은 너희에게서 난 것이 아니요 하나님의 선물이라"},{"book":"에베소서","ref":"에베소서 2:9","topic":"은혜로 인한 구원","text":"행위에서 난 것이 아니니 이는 누구든지 자랑하지 못하게 함이라"},{"book":"에베소서","ref":"에베소서 2:14","topic":"우리의 화평이신 그리스도","text":"그는 우리의 화평이신지라 둘로 하나를 만드사 원수 된 것 곧 중간에 막힌 담을 자기 육체로 허시고"},{"book":"에베소서","ref":"에베소서 4:15","topic":"성장의 목표","text":"오직 사랑 안에서 참된 것을 하여 범사에 그에게까지 자랄지라 그는 머리니 곧 그리스도라"},{"book":"에베소서","ref":"에베소서 4:32","topic":"서로 용서하라","text":"서로 친절하게 하며 불쌍히 여기며 서로 용서하기를 하나님이 그리스도 안에서 너희를 용서하심과 같이 하라"},{"book":"에베소서","ref":"에베소서 5:8","topic":"빛의 열매","text":"너희가 전에는 어둠이더니 이제는 주 안에서 빛이라 빛의 자녀들처럼 행하라"},{"book":"에베소서","ref":"에베소서 5:9","topic":"빛의 열매","text":"빛의 열매는 모든 착함과 의로움과 진실함에 있느니라"},{"book":"에베소서","ref":"에베소서 5:18","topic":"성령의 충만","text":"술 취하지 말라 이는 방탕한 것이니 오직 성령으로 충만함을 받으라"},{"book":"빌립보서","ref":"빌립보서 2:5","topic":"그리스도의 낮아지심","text":"너희 안에 이 마음을 품으라 곧 그리스도 예수의 마음이니"},{"book":"빌립보서","ref":"빌립보서 2:6","topic":"그리스도의 낮아지심","text":"그는 근본 하나님의 본체시나 하나님과 동등됨을 취할 것으로 여기지 아니하시고"},{"book":"빌립보서","ref":"빌립보서 2:7","topic":"그리스도의 낮아지심","text":"오히려 자기를 비워 종의 형체를 가지사 사람들과 같이 되셨고"},{"book":"빌립보서","ref":"빌립보서 2:8","topic":"그리스도의 낮아지심","text":"사람의 모양으로 나타나사 자기를 낮추시고 죽기까지 복종하셨으니 곧 십자가에 죽으심이라"},{"book":"빌립보서","ref":"빌립보서 2:10","topic":"그리스도를 높이심","text":"하늘에 있는 자들과 땅에 있는 자들과 땅 아래에 있는 자들로 모든 무릎을 예수의 이름에 꿇게 하시고"},{"book":"빌립보서","ref":"빌립보서 2:11","topic":"그리스도를 높이심","text":"모든 입으로 예수 그리스도를 주라 시인하여 하나님 아버지께 영광을 돌리게 하셨느니라"},{"book":"빌립보서","ref":"빌립보서 4:6","topic":"염려하지 말라","text":"아무 것도 염려하지 말고 다만 모든 일에 기도와 간구로, 너희 구할 것을 감사함으로 하나님께 아뢰라"},{"book":"빌립보서","ref":"빌립보서 4:7","topic":"염려하지 말라","text":"그리하면 모든 지각에 뛰어난 하나님의 평강이 그리스도 예수 안에서 너희 마음과 생각을 지키시리라"},{"book":"골로새서","ref":"골로새서 1:24","topic":"그리스도의 남은 고난","text":"나는 이제 너희를 위하여 받는 괴로움을 기뻐하고 / 그리스도의 남은 고난을 그의 몸된 교회를 위하여 내 육체에 채우노라"},{"book":"골로새서","ref":"골로새서 3:1","topic":"위의 것을 찾으라","text":"그러므로 너희가 그리스도와 함께 다시 살리심을 받았으면 위의 것을 찾으라 거기는 그리스도께서 하나님 우편에 앉아 계시느니라"},{"book":"골로새서","ref":"골로새서 3:15","topic":"그리스도의 평강","text":"그리스도의 평강이 너희 마음을 주장하게 하라 너희는 평강을 위하여 한 몸으로 부르심을 받았나니 너희는 또한 감사하는 자가 되라"},{"book":"데살로니가전서","ref":"데살로니가전서 5:15","topic":"악으로 악을 갚지 말라","text":"삼가 누가 누구에게든지 악으로 악을 갚지 말게 하고 / 서로 대하든지 모든 사람을 대하든지 항상 선을 따르라"},{"book":"데살로니가전서","ref":"데살로니가전서 5:16","topic":"우리를 향하신 하나님의 뜻","text":"항상 기뻐하라"},{"book":"데살로니가전서","ref":"데살로니가전서 5:17","topic":"우리를 향하신 하나님의 뜻","text":"쉬지 말고 기도하라"},{"book":"데살로니가전서","ref":"데살로니가전서 5:18","topic":"우리를 향하신 하나님의 뜻","text":"범사에 감사하라 이것이 그리스도 예수 안에서 너희를 향하신 하나님의 뜻이니라"},{"book":"디모데전서","ref":"디모데전서 1:15","topic":"죄인 중의 괴수","text":"미쁘다 모든 사람이 받을 만한 이 말이여 그리스도 예수께서 죄인을 구원하시려고 세상에 임하셨다 하였도다 죄인 중에 내가 괴수니라"},{"book":"디모데전서","ref":"디모데전서 2:5","topic":"유일하신 중보자","text":"하나님은 한 분이시요 또 하나님과 사람 사이에 중보자도 한 분이시니 / 곧 사람이신 그리스도 예수라"},{"book":"디모데전서","ref":"디모데전서 4:12","topic":"교역자의 자세","text":"누구든지 네 연소함을 업신여기지 못하게 하고 / 오직 말과 행실과 사랑과 믿음과 정절에 있어서 믿는 자에게 본이 되어"},{"book":"디모데전서","ref":"디모데전서 4:13","topic":"교역자의 자세","text":"내가 이를 때까지 읽는 것과 권하는 것과 가르치는 것에 전념하라"},{"book":"디모데후서","ref":"디모데후서 2:15","topic":"진리의 말씀 분별","text":"너는 진리의 말씀을 옳게 분별하며 / 부끄러울 것이 없는 일꾼으로 인정된 자로 자신을 하나님 앞에 드리기를 힘쓰라"},{"book":"디모데후서","ref":"디모데후서 2:22","topic":"청년의 정욕을 피하라","text":"또한 너는 청년의 정욕을 피하고 / 주를 깨끗한 마음으로 부르는 자들과 함께 의와 믿음과 사랑과 화평을 따르라"},{"book":"디모데후서","ref":"디모데후서 3:16","topic":"성경의 영감","text":"모든 성경은 하나님의 감동으로 된 것으로 교훈과 책망과 바르게 함과 의로 교육하기에 유익하니"},{"book":"디모데후서","ref":"디모데후서 3:17","topic":"성경의 영감","text":"이는 하나님의 사람으로 온전하게 하며 / 모든 선한 일을 행할 능력을 갖추게 하려 함이라"},{"book":"디도서","ref":"디도서 2:14","topic":"선한 일을 열심히 하는 자기 백성","text":"그가 우리를 대신하여 자신을 주심은 모든 불법에서 우리를 속량하시고 우리를 깨끗하게 하사 선한 일을 열심히 하는 자기 백성이 되게 하려 하심이라"},{"book":"히브리서","ref":"히브리서 4:12","topic":"살아 있는 하나님의 말씀","text":"하나님의 말씀은 살아 있고 활력이 있어 좌우에 날선 어떤 검보다도 예리하여 혼과 영과 및 관절과 골수를 찔러 쪼개기까지 하며 / 또 마음의 생각과 뜻을 판단하나니"},{"book":"히브리서","ref":"히브리서 4:16","topic":"은혜의 보좌 앞에 담대히 나아감","text":"그러므로 우리는 긍휼하심을 받고 때를 따라 돕는 은혜를 얻기 위하여 은혜의 보좌 앞에 담대히 나아갈 것이니라"},{"book":"히브리서","ref":"히브리서 9:14","topic":"그리스도의 피의 능력","text":"하물며 영원하신 성령으로 말미암아 흠 없는 자기를 하나님께 드린 그리스도의 피가 어찌 너희 양심을 죽은 행실에서 깨끗하게 하고 / 살아 계신 하나님을 섬기게 하지 못하겠느냐"},{"book":"히브리서","ref":"히브리서 9:27","topic":"죽음의 필연성","text":"한번 죽는 것은 사람에게 정해진 것이요 / 그 후에는 심판이 있으리니"},{"book":"히브리서","ref":"히브리서 11:6","topic":"하나님께 나아가는 자","text":"믿음이 없이는 하나님을 기쁘시게 하지 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 / 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할지니라"},{"book":"히브리서","ref":"히브리서 12:2","topic":"예수를 바라보자","text":"믿음의 주요 또 온전하게 하시는 이인 예수를 바라보자 그는 그 앞에 있는 기쁨을 위하여 십자가를 참으사 부끄러움을 개의치 아니하시더니 하나님 보좌 우편에 앉으셨느니라"},{"book":"야고보서","ref":"야고보서 1:15","topic":"죄의 기원과 결과","text":"욕심이 잉태한즉 / 죄를 낳고 죄가 장성한즉 사망을 낳느니라"},{"book":"야고보서","ref":"야고보서 1:27","topic":"참 경건","text":"하나님 아버지 앞에서 정결하고 / 더러움이 없는 경건은 곧 고아와 과부를 그 환난중에 돌보고 또 자기를 지켜 세속에 물들지 아니하는 그것이니라"},{"book":"야고보서","ref":"야고보서 2:1","topic":"사람을 차별하지 말라","text":"내 형제들아 영광의 주 곧 우리 주 예수 그리스도에 대한 믿음을 너희가 가졌으니 사람을 차별하여 대하지 말라"},{"book":"야고보서","ref":"야고보서 2:26","topic":"참된 믿음은 행함을 수반함","text":"영혼 없는 몸이 죽은 것 같이 행함이 없는 믿음은 죽은 것이니라"},{"book":"야고보서","ref":"야고보서 4:8","topic":"하나님을 가까이 하라","text":"하나님을 가까이하라 그리하면 너희를 가까이하시리라 죄인들아 손을 깨끗이 하라 두 마음을 품은 자들아 마음을 성결하게 하라"},{"book":"야고보서","ref":"야고보서 4:17","topic":"알고도 행치 않는 죄","text":"그러므로 사람이 선을 행할 줄 알고도 행하지 아니하면 죄니라"},{"book":"야고보서","ref":"야고보서 5:13","topic":"기도와 찬송","text":"너희 중에 고난당하는 자가 있느냐 그는 기도할 것이요 / 즐거워하는 자가 있느냐 그는 찬송할지니라"},{"book":"베드로전서","ref":"베드로전서 1:15","topic":"거룩한 자가 되라","text":"오직 너희를 부르신 거룩한 이처럼 너희도 모든 행실에 거룩한 자가 되라"},{"book":"베드로전서","ref":"베드로전서 1:18","topic":"그리스도의 보배로운 피","text":"너희가 알거니와 너희 조상이 물려 준 헛된 행실에서 대속함을 받은 것은 은이나 금 같이 없어질 것으로 된 것이 아니요"},{"book":"베드로전서","ref":"베드로전서 1:19","topic":"그리스도의 보배로운 피","text":"오직 흠 없고 점 없는 어린 양 같은 그리스도의 보배로운 피로 된 것이니라"},{"book":"베드로전서","ref":"베드로전서 1:23","topic":"말씀을 통한 중생","text":"너희가 거듭난 것은 썩어질 씨로 된 것이 아니요 썩지 아니할 씨로 된 것이니 살아 있고 항상 있는 하나님의 말씀으로 되었느니라"},{"book":"베드로전서","ref":"베드로전서 2:9","topic":"하나님의 백성","text":"그러나 너희는 택하신 족속이요 왕 같은 제사장들이요 / 거룩한 나라요 그의 소유가 된 백성이니 이는 너희를 어두운 데서 불러내어 그의 기이한 빛에 들어가게 하신 이의 아름다운 덕을 선포하게 하려 하심이라"},{"book":"베드로전서","ref":"베드로전서 4:8","topic":"사랑은 허다한 죄를 덮음","text":"무엇보다도 뜨겁게 서로 사랑할지니 사랑은 허다한 죄를 덮느니라"},{"book":"베드로후서","ref":"베드로후서 1:20","topic":"성경의 예언","text":"먼저 알 것은 성경의 모든 예언은 사사로이 풀 것이 아니니"},{"book":"베드로후서","ref":"베드로후서 1:21","topic":"성경의 예언","text":"예언은 언제든지 사람의 뜻으로 낸 것이 아니요 오직 성령의 감동하심을 받은 사람들이 하나님께 받아 말한 것임이라"},{"book":"베드로후서","ref":"베드로후서 3:13","topic":"새 하늘과 새 땅","text":"우리는 그의 약속대로 의가 있는 곳인 새 하늘과 새 땅을 바라보도다"},{"book":"베드로후서","ref":"베드로후서 3:14","topic":"새 하늘과 새 땅","text":"그러므로 사랑하는 자들아 너희가 이것을 바라보나니 주 앞에서 점도 없고 흠도 없이 평강 가운데서 나타나기를 힘쓰라"},{"book":"요한일서","ref":"요한일서 1:9","topic":"죄 자백과 용서","text":"만일 우리가 우리 죄를 자백하면 그는 미쁘시고 의로우사 우리 죄를 사하시며 우리를 모든 불의에서 깨끗하게 하실 것이요"},{"book":"요한일서","ref":"요한일서 4:10","topic":"하나님이 먼저 우리를 사랑하심","text":"사랑은 여기 있으니 우리가 하나님을 사랑한 것이 아니요 하나님이 우리를 사랑하사 우리 죄를 속하기 위하여 화목 제물로 그 아들을 보내셨음이라"},{"book":"요한일서","ref":"요한일서 4:20","topic":"형제 사랑과 하나님 사랑","text":"누구든지 하나님을 사랑하노라 하고 / 그 형제를 미워하면 이는 거짓말하는 자니 보는 바 그 형제를 사랑하지 아니하는 자는 보지 못하는 바 하나님을 사랑할 수 없느니라"},{"book":"요한일서","ref":"요한일서 5:4","topic":"세상을 이기는 승리","text":"무릇 하나님께로부터 난 자마다 세상을 이기느니라 세상을 이기는 승리는 이것이니 우리의 믿음이니라"},{"book":"요한일서","ref":"요한일서 5:12","topic":"아들과 생명","text":"아들이 있는 자에게는 생명이 있고 하나님의 아들이 없는 자에게는 생명이 없느니라"},{"book":"요한삼서","ref":"요한삼서 1:11","topic":"선을 행하는 자","text":"사랑하는 자여 악한 것을 본받지 말고 선한 것을 본받으라 선을 행하는 자는 하나님께 속하고 / 악을 행하는 자는 하나님을 뵈옵지 못하였느니라"},{"book":"요한계시록","ref":"요한계시록 3:20","topic":"예수님의 초청","text":"볼지어다 내가 문 밖에 서서 두드리노니 누구든지 내 음성을 듣고 문을 열면 내가 그에게로 들어가 그와 더불어 먹고 그는 나와 더불어 먹으리라"},{"book":"마태복음","ref":"마태복음 3:16","topic":"하나님의 아들과 세례","text":"예수께서 세례를 받으시고 곧 물에서 올라오실새 하늘이 열리고 하나님의 성령이 비둘기 같이 내려 자기 위에 임하심을 보시더니"},{"book":"마태복음","ref":"마태복음 3:17","topic":"하나님의 아들과 세례","text":"하늘로부터 소리가 있어 말씀하시되 이는 내 사랑하는 아들이요 / 내 기뻐하는 자라 하시니라"},{"book":"마태복음","ref":"마태복음 5:17","topic":"예수님과 율법","text":"내가 율법이나 선지자를 폐하러 온 줄로 생각하지 말라 폐하러 온 것이 아니요 완전하게 하려 함이라"},{"book":"마태복음","ref":"마태복음 6:8-9상","topic":"하나님의 예지와 기도","text":"그러므로 그들을 본받지 말라 구하기 전에 너희에게 있어야 할 것을 하나님 너희 아버지께서 아시느니라. 그러므로 너희는 이렇게 기도하라."},{"book":"마태복음","ref":"마태복음 7:13","topic":"좁은 문과 넓은 문","text":"좁은 문으로 들어가라 멸망으로 인도하는 문은 크고 그 길이 넓어 그리로 들어가는 자가 많고"},{"book":"마태복음","ref":"마태복음 7:14","topic":"좁은 문과 넓은 문","text":"생명으로 인도하는 문은 좁고 길이 협착하여 찾는 자가 적음이라"},{"book":"마태복음","ref":"마태복음 9:13","topic":"제사와 긍휼","text":"너희는 가서 내가 긍휼을 원하고 / 제사를 원하지 아니하노라 하신 뜻이 무엇인지 배우라 나는 의인을 부르러 온 것이 아니요 죄인을 부르러 왔노라 하시니라"},{"book":"마태복음","ref":"마태복음 11:28","topic":"예수님의 초청","text":"수고하고 무거운 짐 진 자들아 다 내게로 오라 내가 너희를 쉬게 하리라"},{"book":"마태복음","ref":"마태복음 11:29","topic":"예수님의 초청","text":"나는 마음이 온유하고 겸손하니 / 나의 멍에를 메고 내게 배우라 그리하면 너희 마음이 쉼을 얻으리니"},{"book":"마태복음","ref":"마태복음 11:30","topic":"예수님의 초청","text":"이는 내 멍에는 쉽고 내 짐은 가벼움이라 하시니라"},{"book":"마태복음","ref":"마태복음 16:18","topic":"교회의 기초","text":"또 내가 네게 이르노니 너는 베드로라 내가 이 반석 위에 내 교회를 세우리니 음부의 권세가 이기지 못하리라"},{"book":"마태복음","ref":"마태복음 16:27","topic":"그리스도의 심판","text":"인자가 아버지의 영광으로 그 천사들과 함께 오리니 그 때에 각 사람이 행한 대로 갚으리라"},{"book":"마태복음","ref":"마태복음 18:19","topic":"합심 기도","text":"진실로 다시 너희에게 이르노니 너희 중의 두 사람이 땅에서 합심하여 무엇이든지 구하면 하늘에 계신 내 아버지께서 그들을 위하여 이루게 하시리라"},{"book":"마태복음","ref":"마태복음 18:20","topic":"합심 기도","text":"두세 사람이 내 이름으로 모인 곳에는 나도 그들 중에 있느니라"},{"book":"마가복음","ref":"마가복음 12:30","topic":"율법의 강령","text":"네 마음을 다하고 목숨을 다하고 뜻을 다하고 / 힘을 다하여 주 너의 하나님을 사랑하라 하신 것이요,"},{"book":"마가복음","ref":"마가복음 12:31","topic":"율법의 강령","text":"둘째는 이것이니 네 이웃을 네 자신과 같이 사랑하라 하신 것이라 이보다 더 큰 계명이 없느니라"},{"book":"마가복음","ref":"마가복음 13:13","topic":"끝까지 견디는 자","text":"또 너희가 내 이름으로 말미암아 모든 사람에게 미움을 받을 것이나 끝까지 견디는 자는 구원을 받으리라"},{"book":"누가복음","ref":"누가복음 4:18","topic":"가난한 자에게 복음을 전하신 그리스도","text":"주의 성령이 내게 임하셨으니 이는 가난한 자에게 복음을 전하게 하시려고 내게 기름을 부으시고 나를 보내사 포로 된 자에게 자유를, 눈 먼 자에게 다시 보게 함을 전파하며 눌린 자를 자유롭게 하고"},{"book":"누가복음","ref":"누가복음 11:13","topic":"성령을 주시는 하늘 아버지","text":"너희가 악할지라도 좋은 것을 자식에게 줄 줄 알거든 하물며 너희 하늘 아버지께서 구하는 자에게 성령을 주시지 않겠느냐 하시니라"},{"book":"누가복음","ref":"누가복음 12:15","topic":"탐심을 물리치라","text":"그들에게 이르시되 삼가 모든 탐심을 물리치라 사람의 생명이 그 소유의 넉넉한 데 있지 아니하니라 하시고"},{"book":"요한복음","ref":"요한복음 1:1","topic":"성부와 성자의 동일 본질","text":"태초에 말씀이 계시니라 이 말씀이 하나님과 함께 계셨으니 이 말씀은 곧 하나님이시니라"},{"book":"요한복음","ref":"요한복음 5:39","topic":"성경과 그리스도","text":"너희가 성경에서 영생을 얻는 줄 생각하고 / 성경을 연구하거니와 이 성경이 곧 내게 대하여 증언하는 것이니라"},{"book":"요한복음","ref":"요한복음 6:68","topic":"영생의 말씀","text":"시몬 베드로가 대답하되 / 주여 영생의 말씀이 주께 있사오니 우리가 누구에게로 가오리이까"},{"book":"요한복음","ref":"요한복음 6:69","topic":"영생의 말씀","text":"우리가 주는 하나님의 거룩하신 자이신 줄 믿고 알았사옵나이다"},{"book":"요한복음","ref":"요한복음 15:26","topic":"성부로부터 나오시는 성령","text":"내가 아버지께로부터 너희에게 보낼 보혜사 곧 아버지께로부터 나오시는 진리의 성령이 오실 때에 그가 나를 증언하실 것이요"},{"book":"요한복음","ref":"요한복음 20:28","topic":"그리스도의 신성","text":"도마가 대답하여 이르되 나의 주님이시요 나의 하나님이시니이다"},{"book":"사도행전","ref":"사도행전 2:42","topic":"초대교회의 모습","text":"그들이 사도의 가르침을 받아 서로 교제하고 / 떡을 떼며 오로지 기도하기를 힘쓰니라"},{"book":"사도행전","ref":"사도행전 20:32","topic":"은혜의 말씀","text":"지금 내가 여러분을 주와 및 그 은혜의 말씀에 부탁하노니 그 말씀이 여러분을 능히 든든히 세우사 거룩하게 하심을 입은 모든 자 가운데 기업이 있게 하시리라"},{"book":"로마서","ref":"로마서 1:17","topic":"복음과 하나님의 의","text":"복음에는 하나님의 의가 나타나서 믿음으로 믿음에 이르게 하나니 기록된바 오직 의인은 믿음으로 말미암아 살리라 함과 같으니라"},{"book":"로마서","ref":"로마서 1:20","topic":"자연계시의 역할. 핑계하지 못함","text":"창세로부터 그의 보이지 아니하는 것들 곧 그의 영원하신 능력과 신성이 그가 만드신 만물에 분명히 보여 알려졌나니 그러므로 그들이 핑계하지 못할지니라"},{"book":"로마서","ref":"로마서 3:20","topic":"율법의 기능","text":"그러므로 율법의 행위로 그의 앞에 의롭다 하심을 얻을 육체가 없나니 율법으로는 죄를 깨달음이니라"},{"book":"로마서","ref":"로마서 5:12","topic":"원죄","text":"그러므로 한 사람으로 말미암아 죄가 세상에 들어오고 죄로 말미암아 사망이 들어왔나니 이와 같이 모든 사람이 죄를 지었으므로 사망이 모든 사람에게 이르렀느니라"},{"book":"로마서","ref":"로마서 8:9","topic":"하나님의 영이 거하심","text":"만일 너희 속에 하나님의 영이 거하시면 너희가 육신에 있지 아니하고 / 영에 있나니 누구든지 그리스도의 영이 없으면 그리스도의 사람이 아니라"},{"book":"로마서","ref":"로마서 8:30","topic":"하나님의 예정과 구원의 서정","text":"또 미리 정하신 그들을 또한 부르시고 부르신 그들을 또한 / 의롭다 하시고 의롭다 하신 그들을 또한 영화롭게 하셨느니라"},{"book":"로마서","ref":"로마서 9:18","topic":"이중 예정: 선택과 유기","text":"그런즉 하나님께서 하고자 하시는 자를 긍휼히 여기시고 하고자 하시는 자를 완악하게 하시느니라"},{"book":"로마서","ref":"로마서 10:17","topic":"믿음과 말씀","text":"그러므로 믿음은 들음에서 나며 들음은 그리스도의 말씀으로 말미암았느니라"},{"book":"로마서","ref":"로마서 12:2","topic":"이 세대를 본받지 말라","text":"너희는 이 세대를 본받지 말고 오직 마음을 새롭게 함으로 변화를 받아 하나님의 선하시고 기뻐하시고 온전하신 뜻이 무엇인지 분별하도록 하라"},{"book":"고린도전서","ref":"고린도전서 1:18","topic":"십자가의 도","text":"십자가의 도가 멸망하는 자들에게는 미련한 것이요 / 구원을 받는 우리에게는 하나님의 능력이라"},{"book":"고린도전서","ref":"고린도전서 1:21","topic":"전도의 미련한 것","text":"하나님의 지혜에 있어서는 이 세상이 자기 지혜로 하나님을 알지 못하므로 하나님께서 전도의 미련한 것으로 믿는 자들을 구원하시기를 기뻐하셨도다"},{"book":"고린도전서","ref":"고린도전서 1:23","topic":"십자가에 못 박힌 그리스도","text":"우리는 십자가에 못 박힌 그리스도를 전하니 / 유대인에게는 거리끼는 것이요 이방인에게는 미련한 것이로되"},{"book":"고린도전서","ref":"고린도전서 1:24","topic":"십자가에 못 박힌 그리스도","text":"오직 부르심을 받은 자들에게는 유대인이나 헬라인이나 그리스도는 하나님의 능력이요 / 하나님의 지혜니라"},{"book":"고린도전서","ref":"고린도전서 2:10","topic":"성경과 성령의 증거","text":"오직 하나님이 성령으로 이것을 우리에게 보이셨으니 성령은 모든 것 곧 하나님의 깊은 것까지도 통달하시느니라"},{"book":"고린도전서","ref":"고린도전서 10:13","topic":"감당할 시험","text":"사람이 감당할 시험 밖에는 너희가 당한 것이 없나니 오직 하나님은 미쁘사 너희가 감당하지 못할 시험 당함을 허락하지 아니하시고 시험 당할 즈음에 또한 / 피할 길을 내사 너희로 능히 감당하게 하시느니라"},{"book":"고린도전서","ref":"고린도전서 10:16","topic":"성찬의 의미","text":"우리가 축복하는 바 축복의 잔은 그리스도의 피에 참여함이 아니며 우리가 떼는 떡은 그리스도의 몸에 참여함이 아니냐"},{"book":"고린도전서","ref":"고린도전서 10:32","topic":"다른 사람의 유익","text":"유대인에게나 헬라인에게나 하나님의 교회에나 거치는 자가 되지 말고"},{"book":"고린도전서","ref":"고린도전서 10:33","topic":"다른 사람의 유익","text":"나와 같이 모든 일에 모든 사람을 기쁘게 하여 자신의 유익을 구하지 아니하고 / 많은 사람의 유익을 구하여 그들로 구원을 받게 하라"},{"book":"고린도전서","ref":"고린도전서 12:13","topic":"한 성령으로 세례 받아 한 몸이 됨","text":"우리가 유대인이나 헬라인이나 종이나 자유인이나 다 한 성령으로 세례를 받아 한 몸이 되었고 또 다 한 성령을 마시게 하셨느니라"},{"book":"고린도전서","ref":"고린도전서 13:2","topic":"사랑의 중요성","text":"내가 예언하는 능력이 있어 모든 비밀과 모든 지식을 알고 또 산을 옮길 만한 모든 믿음이 있을지라도 사랑이 없으면 내가 아무 것도 아니요"},{"book":"고린도전서","ref":"고린도전서 13:3","topic":"사랑의 중요성","text":"내가 내게 있는 모든 것으로 구제하고 / 또 내 몸을 불사르게 내줄지라도 사랑이 없으면 내게 아무 유익이 없느니라"},{"book":"고린도전서","ref":"고린도전서 15:20","topic":"죽은 자의 부활","text":"그러나 이제 그리스도께서 죽은 자 가운데서 다시 살아나사 잠자는 자들의 첫 열매가 되셨도다"},{"book":"고린도전서","ref":"고린도전서 15:21","topic":"죽은 자의 부활","text":"사망이 한 사람으로 말미암았으니 죽은 자의 부활도 한 사람으로 말미암는도다"},{"book":"고린도전서","ref":"고린도전서 15:58","topic":"주의 일에 더욱 힘쓰라","text":"그러므로 내 사랑하는 형제들아 견실하며 / 흔들리지 말고 항상 주의 일에 더욱 힘쓰는 자들이 되라 이는 너희 수고가 주 안에서 헛되지 않은 줄 앎이라"},{"book":"고린도후서","ref":"고린도후서 2:17","topic":"말씀을 전하는 자의 자세","text":"우리는 수많은 사람들처럼 하나님의 말씀을 혼잡하게 하지 아니하고 / 곧 순전함으로 하나님께 받은 것 같이 하나님 앞에서와 그리스도 안에서 말하노라"},{"book":"고린도후서","ref":"고린도후서 4:6","topic":"하나님의 영광을 아는 빛","text":"어두운 데에 빛이 비치라 말씀하셨던 그 하나님께서 예수 그리스도의 얼굴에 있는 하나님의 영광을 아는 빛을 우리 마음에 비추셨느니라"},{"book":"고린도후서","ref":"고린도후서 5:9","topic":"그리스도의 심판대 앞에 나타남","text":"그런즉 우리는 몸으로 있든지 떠나든지 주를 기쁘시게 하는 자가 되기를 힘쓰노라"},{"book":"고린도후서","ref":"고린도후서 5:10","topic":"그리스도의 심판대 앞에 나타남","text":"이는 우리가 다 반드시 그리스도의 심판대 앞에 나타나게 되어 각각 선악간에 그 몸으로 행한 것을 따라 받으려 함이라"},{"book":"고린도후서","ref":"고린도후서 5:20","topic":"하나님과 화목하라","text":"그러므로 우리가 그리스도를 대신하여 사신이 되어 하나님이 우리를 통하여 너희를 권면하시는 것 같이 그리스도를 대신하여 간청하노니 너희는 하나님과 화목하라"},{"book":"갈라디아서","ref":"갈라디아서 3:10","topic":"율법 행위에 속한 자들은 저주 아래 있음","text":"무릇 율법 행위에 속한 자들은 저주 아래에 있나니 기록된 바 누구든지 율법 책에 기록된 대로 모든 일을 항상 행하지 아니하는 자는 저주 아래에 있는 자라 하였음이라"},{"book":"갈라디아서","ref":"갈라디아서 3:13","topic":"그리스도께서 우리를 위하여 저주를 받음","text":"그리스도께서 우리를 위하여 저주를 받은 바 되사 율법의 저주에서 우리를 속량하셨으니 기록된 바 나무에 달린 자마다 저주 아래에 있는 자라 하였음이라"},{"book":"에베소서","ref":"에베소서 1:5","topic":"예정과 예정의 목적","text":"그 기쁘신 뜻대로 우리를 예정하사 예수 그리스도로 말미암아 자기의 아들들이 되게 하셨으니"},{"book":"에베소서","ref":"에베소서 1:6","topic":"예정과 예정의 목적","text":"이는 그가 사랑하시는 자 안에서 우리에게 거저 주시는 바 그의 은혜의 영광을 찬송하게 하려는 것이라"},{"book":"에베소서","ref":"에베소서 1:23","topic":"교회는 그리스도의 몸","text":"교회는 그의 몸이니 만물 안에서 만물을 충만하게 하시는 이의 충만함이니라"},{"book":"에베소서","ref":"에베소서 2:5","topic":"함께 하늘에 앉히심","text":"허물로 죽은 우리를 그리스도와 함께 살리셨고 (너희는 은혜로 구원을 얻은 것이라)"},{"book":"에베소서","ref":"에베소서 2:6","topic":"함께 하늘에 앉히심","text":"또 함께 일으키사 그리스도 예수 안에서 함께 하늘에 앉히시니"},{"book":"에베소서","ref":"에베소서 4:11","topic":"직분을 세우신 목적","text":"그가 어떤 사람은 사도로, 어떤 사람은 선지자로, 어떤 사람은 복음 전하는 자로, 어떤 사람은 목사와 교사로 삼으셨으니"},{"book":"에베소서","ref":"에베소서 4:12","topic":"직분을 세우신 목적","text":"이는 성도를 온전하게 하여 봉사의 일을 하게 하며 / 그리스도의 몸을 세우려 하심이라"},{"book":"에베소서","ref":"에베소서 5:1","topic":"사랑 가운데서 행하라","text":"그러므로 사랑을 받는 자녀 같이 너희는 하나님을 본받는 자가 되고"},{"book":"에베소서","ref":"에베소서 5:2","topic":"사랑 가운데서 행하라","text":"그리스도께서 너희를 사랑하신 것 같이 너희도 사랑 가운데서 행하라 그는 우리를 위하여 자신을 버리사 향기로운 제물과 희생제물로 하나님께 드리셨느니라"},{"book":"에베소서","ref":"에베소서 6:12","topic":"우리의 씨름","text":"우리의 씨름은 혈과 육을 상대하는 것이 아니요 통치자들과 권세들과 이 어둠의 세상 주관자들과 하늘에 있는 악의 영들을 상대함이라"},{"book":"빌립보서","ref":"빌립보서 2:12","topic":"인간의 자유와 하나님의 주권","text":"그러므로 나의 사랑하는 자들아 너희가 나 있을 때뿐 아니라 더욱 지금 나 없을 때에도 항상 복종하여 두렵고 떨림으로 너희 구원을 이루라."},{"book":"빌립보서","ref":"빌립보서 2:13","topic":"인간의 자유와 하나님의 주권","text":"너희 안에서 행하시는 이는 하나님이시니 / 자기의 기쁘신 뜻을 위하여 너희에게 소원을 두고 행하게 하시나니"},{"book":"빌립보서","ref":"빌립보서 3:7","topic":"가장 고상한 지식","text":"그러나 무엇이든지 내게 유익하던 것을 내가 그리스도를 위하여 다 해로 여길뿐더러"},{"book":"빌립보서","ref":"빌립보서 3:8","topic":"가장 고상한 지식","text":"또한 모든 것을 해로 여김은 내 주 그리스도 예수를 아는 지식이 가장 고상하기 때문이라"},{"book":"빌립보서","ref":"빌립보서 3:20","topic":"우리의 시민권은 하늘에","text":"그러나 우리의 시민권은 하늘에 있는지라 거기로부터 구원하는 자 곧 주 예수 그리스도를 기다리노니"},{"book":"빌립보서","ref":"빌립보서 3:21","topic":"우리의 시민권은 하늘에","text":"그는 만물을 자기에게 복종하게 하실 수 있는 자의 역사로 우리의 낮은 몸을 자기 영광의 몸의 형체와 같이 변하게 하시리라"},{"book":"골로새서","ref":"골로새서 1:28","topic":"그리스도를 전파하는 목적","text":"우리가 그를 전파하여 각 사람을 권하고 / 모든 지혜로 각 사람을 가르침은 각 사람을 그리스도 안에서 완전한 자로 세우려 함이니"},{"book":"골로새서","ref":"골로새서 1:29","topic":"그리스도를 전파하는 목적","text":"이를 위하여 나도 내 속에서 능력으로 역사하시는 이의 역사를 따라 힘을 다하여 수고하노라"},{"book":"골로새서","ref":"골로새서 2:12","topic":"세례와 믿음","text":"너희가 세례로 그리스도와 함께 장사되고 또 죽은 자들 가운데서 그를 일으키신 하나님의 역사를 믿음으로 말미암아 그 안에서 함께 일으키심을 받았느니라"},{"book":"골로새서","ref":"골로새서 3:9","topic":"새 사람","text":"너희가 서로 거짓말을 하지 말라 옛 사람과 그 행위를 벗어 버리고"},{"book":"골로새서","ref":"골로새서 3:10","topic":"새 사람","text":"새 사람을 입었으니 이는 자기를 창조하신 이의 형상을 따라 지식에까지 새롭게 하심을 입은 자니라"},{"book":"데살로니가전서","ref":"데살로니가전서 2:19","topic":"우리의 소망","text":"우리의 소망이나 기쁨이나 자랑의 면류관이 무엇이냐 그가 강림하실 때 우리 주 예수 앞에 너희가 아니냐"},{"book":"데살로니가전서","ref":"데살로니가전서 2:20","topic":"우리의 소망","text":"너희는 우리의 영광이요 기쁨이니라"},{"book":"데살로니가전서","ref":"데살로니가전서 4:7","topic":"우리를 부르신 목적","text":"하나님이 우리를 부르심은 부정하게 하심이 아니요 거룩하게 하심이니"},{"book":"데살로니가전서","ref":"데살로니가전서 4:8","topic":"우리를 부르신 목적","text":"그러므로 저버리는 자는 사람을 저버림이 아니요 너희에게 그의 성령을 주신 하나님을 저버림이니라"},{"book":"데살로니가전서","ref":"데살로니가전서 5:21","topic":"합당한 분별","text":"범사에 헤아려 좋은 것을 취하고"},{"book":"데살로니가전서","ref":"데살로니가전서 5:22","topic":"합당한 분별","text":"악은 어떤 모양이라도 버리라"},{"book":"데살로니가후서","ref":"데살로니가후서 3:10","topic":"노동의 의무","text":"우리가 너희와 함께 있을 때에도 너희에게 명하기를 누구든지 일하기 싫어하거든 먹지도 말게 하라 하였더니"},{"book":"디모데전서","ref":"디모데전서 1:5","topic":"교훈의 목적","text":"이 교훈의 목적은 청결한 마음과 선한 양심과 거짓이 없는 믿음에서 나오는 사랑이거늘"},{"book":"디모데전서","ref":"디모데전서 2:1","topic":"지도자들을 위한 기도","text":"그러므로 내가 첫째로 권하노니 모든 사람을 위하여 간구와 기도와 도고와 감사를 하되"},{"book":"디모데전서","ref":"디모데전서 2:2","topic":"지도자들을 위한 기도","text":"임금들과 높은 지위에 있는 모든 사람을 위하여 하라 이는 우리가 모든 경건과 단정함으로 고요하고 / 평안한 생활을 하려 함이라"},{"book":"디모데전서","ref":"디모데전서 3:2","topic":"감독의 자질","text":"그러므로 감독은 책망할 것이 없으며 한 아내의 남편이 되며 절제하며 / 신중하며 단정하며 나그네를 대접하며 가르치기를 잘하며"},{"book":"디모데전서","ref":"디모데전서 3:3","topic":"감독의 자질","text":"술을 즐기지 아니하며 구타하지 아니하며 / 오직 관용하며 다투지 아니하며 돈을 사랑하지 아니하며"},{"book":"디모데전서","ref":"디모데전서 3:15","topic":"진리의 기둥과 터인 교회","text":"만일 내가 지체하면 너로 하여금 하나님의 집에서 어떻게 행하여야 할지를 알게 하려 함이니 이 집은 살아 계신 하나님의 교회요 진리의 기둥과 터이니라"},{"book":"디모데전서","ref":"디모데전서 6:10","topic":"돈을 사랑함은 일만 악의 뿌리","text":"돈을 사랑함이 일만 악의 뿌리가 되나니 이것을 탐내는 자들은 미혹을 받아 믿음에서 떠나 많은 근심으로써 자기를 찔렀도다"},{"book":"디모데전서","ref":"디모데전서 6:17","topic":"부자들의 할 일","text":"네가 이 세대에서 부한 자들을 명하여 마음을 높이지 말고 정함이 없는 재물에 소망을 두지 말고 오직 우리에게 모든 것을 후히 주사 누리게 하시는 하나님께 두며"},{"book":"디모데전서","ref":"디모데전서 6:18","topic":"부자들의 할 일","text":"선을 행하고 선한 사업을 많이 하고 / 나누어 주기를 좋아하며 너그러운 자가 되게 하라"},{"book":"디모데후서","ref":"디모데후서 1:9","topic":"효력 있는 부르심","text":"하나님이 우리를 구원하사 거룩하신 소명으로 부르심은 우리의 행위대로 하심이 아니요 오직 자기의 뜻과 영원 전부터 그리스도 예수 안에서 우리에게 주신 은혜대로 하심이라"},{"book":"디모데후서","ref":"디모데후서 2:11","topic":"함께 죽고 함께 삶","text":"미쁘다 이 말이여 우리가 주와 함께 죽었으면 또한 / 함께 살 것이요"},{"book":"디모데후서","ref":"디모데후서 2:12","topic":"함께 죽고 함께 삶","text":"참으면 또한 함께 왕 노릇 할 것이요 / 우리가 주를 부인하면 주도 우리를 부인하실 것이라"},{"book":"디모데후서","ref":"디모데후서 2:13","topic":"함께 죽고 함께 삶","text":"우리는 미쁨이 없을지라도 주는 항상 미쁘시니 / 자기를 부인하실 수 없으시리라"},{"book":"디모데후서","ref":"디모데후서 2:14","topic":"말다툼을 하지 말라","text":"너는 그들로 이 일을 기억하게 하여 말다툼을 하지 말라고 하나님 앞에서 엄히 명하라 이는 유익이 하나도 없고 도리어 듣는 자들을 망하게 함이라"},{"book":"디모데후서","ref":"디모데후서 4:1","topic":"말씀을 전파하라","text":"하나님 앞과 살아 있는 자와 죽은 자를 심판하실 그리스도 예수 앞에서 그가 나타나실 것과 그의 나라를 두고 엄히 명하노니"},{"book":"디모데후서","ref":"디모데후서 4:2","topic":"말씀을 전파하라","text":"너는 말씀을 전파하라 때를 얻든지 못 얻든지 항상 힘쓰라 범사에 오래 참음과 가르침으로 경책하며 경계하며 권하라"},{"book":"디도서","ref":"디도서 3:5","topic":"구원은 우리의 의로운 행위로 하지 않음","text":"우리를 구원하시되 우리가 행한 바 의로운 행위로 말미암지 아니하고 / 오직 그의 긍휼하심을 따라 중생의 씻음과 성령의 새롭게 하심으로 하셨나니"},{"book":"히브리서","ref":"히브리서 1:1","topic":"아들을 통한 계시","text":"옛적에 선지자들을 통하여 여러 부분과 여러 모양으로 우리 조상들에게 말씀하신 하나님이"},{"book":"히브리서","ref":"히브리서 1:2","topic":"아들을 통한 계시","text":"이 모든 날 마지막에는 아들을 통하여 우리에게 말씀하셨으니"},{"book":"히브리서","ref":"히브리서 3:1","topic":"대제사장이신 예수","text":"그러므로 함께 하늘의 부르심을 받은 거룩한 형제들아 우리가 믿는 도리의 사도이시며 대제사장이신 예수를 깊이 생각하라 4:14 (그리스도의 승천) 그러므로 우리에게 큰 대제사장이 계시니 / 승천하신 이 곧 하나님의 아들 예수시라 우리가 믿는 도리를 굳게 잡을지어다"},{"book":"히브리서","ref":"히브리서 4:15","topic":"그리스도는 우리 연약함을 동정하심","text":"우리에게 있는 대제사장은 우리 연약함을 동정하지 못하실 이가 아니요 모든 일에 우리와 똑같이 시험을 받으신 이로되 죄는 없으시니라"},{"book":"히브리서","ref":"히브리서 9:28","topic":"단번에 자기를 드리신 그리스도","text":"이와 같이 그리스도도 많은 사람의 죄를 담당하시려고 단번에 드리신 바 되셨고 구원에 이르게 하기 위하여 죄와 상관없이 자기를 바라는 자들에게 두 번째 나타나시리라"},{"book":"히브리서","ref":"히브리서 10:23","topic":"서로 돌아보고 권하자","text":"또 약속하신 이는 미쁘시니 / 우리가 믿는 도리의 소망을 움직이지 말며 굳게 잡고"},{"book":"히브리서","ref":"히브리서 10:24","topic":"서로 돌아보고 권하자","text":"서로 돌아보아 사랑과 선행을 격려하며"},{"book":"히브리서","ref":"히브리서 10:25","topic":"서로 돌아보고 권하자","text":"모이기를 폐하는 어떤 사람들의 습관과 같이 하지 말고 오직 권하여 그 날이 가까움을 볼수록 더욱 그리하자"},{"book":"히브리서","ref":"히브리서 11:1","topic":"믿음이란 무엇인가?","text":"믿음은 바라는 것들의 실상이요 / 보이지 않는 것들의 증거니"},{"book":"히브리서","ref":"히브리서 11:2","topic":"믿음이란 무엇인가?","text":"선진들이 이로써 증거를 얻었느니라"},{"book":"히브리서","ref":"히브리서 13:1","topic":"형제 사랑과 손님 대접","text":"형제 사랑하기를 계속하고"},{"book":"히브리서","ref":"히브리서 13:2","topic":"형제 사랑과 손님 대접","text":"손님 대접하기를 잊지 말라 이로써 부지중에 천사들을 대접한 이들이 있었느니라"},{"book":"히브리서","ref":"히브리서 13:5","topic":"있는 바를 족한 줄로 알라","text":"돈을 사랑하지 말고 있는 바를 족한 줄로 알라 그가 친히 말씀하시기를 내가 결코 너희를 버리지 아니하고 / 너희를 떠나지 아니하리라 하셨느니라"},{"book":"야고보서","ref":"야고보서 1:5","topic":"후히 주시고 꾸짖지 아니하시는 하나님","text":"너희 중에 누구든지 지혜가 부족하거든 모든 사람에게 후히 주시고 꾸짖지 아니하시는 하나님께 구하라 그리하면 주시리라"},{"book":"야고보서","ref":"야고보서 5:15","topic":"믿음의 기도는 병든 자를 구원함","text":"믿음의 기도는 병든 자를 구원하리니 주께서 그를 일으키시리라 혹시 죄를 범하였을지라도 사하심을 받으리라"},{"book":"야고보서","ref":"야고보서 5:16","topic":"믿음의 기도는 병든 자를 구원함","text":"그러므로 너희 죄를 서로 고백하며 / 병이 낫기를 위하여 서로 기도하라 의인의 간구는 역사하는 힘이 큼이니라"},{"book":"베드로전서","ref":"베드로전서 1:22","topic":"뜨겁게 서로 사랑하라","text":"너희가 진리를 순종함으로 너희 영혼을 깨끗하게 하여 거짓이 없이 형제를 사랑하기에 이르렀으니 마음으로 뜨겁게 서로 사랑하라"},{"book":"베드로전서","ref":"베드로전서 1:24","topic":"세세토록 있는 하나님의 말씀","text":"그러므로 모든 육체는 풀과 같고 그 모든 영광은 풀의 꽃과 같으니 풀은 마르고 꽃은 떨어지되"},{"book":"베드로전서","ref":"베드로전서 1:25","topic":"세세토록 있는 하나님의 말씀","text":"오직 주의 말씀은 세세토록 있도다 하였으니 너희에게 전한 복음이 곧 이 말씀이니라"},{"book":"베드로전서","ref":"베드로전서 2:10","topic":"교회는 하나님의 백성","text":"너희가 전에는 백성이 아니더니 이제는 하나님의 백성이요 / 전에는 긍휼을 얻지 못하였더니 이제는 긍휼을 얻은 자니라"},{"book":"베드로전서","ref":"베드로전서 3:7","topic":"남편의 의무","text":"남편들아 이와 같이 지식을 따라 너희 아내와 동거하고 그를 더 연약한 그릇이요 / 또 생명의 은혜를 함께 이어받을 자로 알아 귀히 여기라 이는 너희 기도가 막히지 아니하게 하려 함이라"},{"book":"베드로전서","ref":"베드로전서 5:8","topic":"근신하라 깨어라","text":"근신하라 깨어라 너희 대적 마귀가 우는 사자 같이 두루 다니며 삼킬 자를 찾나니"},{"book":"베드로전서","ref":"베드로전서 5:9","topic":"근신하라 깨어라","text":"너희는 믿음을 굳건하게 하여 그를 대적하라 이는 세상에 있는 너희 형제들도 동일한 고난을 당하는 줄을 앎이라"},{"book":"베드로후서","ref":"베드로후서 3:18","topic":"그리스도의 은혜와 그를 아는 지식","text":"오직 우리 주 곧 구주 예수 그리스도의 은혜와 그를 아는 지식에서 자라 가라 영광이 이제와 영원한 날까지 그에게 있을지어다"},{"book":"요한일서","ref":"요한일서 2:1","topic":"대언자 예수 그리스도","text":"나의 자녀들아 내가 이것을 너희에게 씀은 너희로 죄를 범하지 않게 하려 함이라 만일 누가 죄를 범하여도 아버지 앞에서 우리에게 대언자가 있으니 곧 의로우신 예수 그리스도시라"},{"book":"요한일서","ref":"요한일서 2:2","topic":"대언자 예수 그리스도","text":"그는 우리 죄를 위한 화목제물이니 우리만 위할 뿐 아니요 온 세상의 죄를 위하심이라"},{"book":"요한일서","ref":"요한일서 3:4","topic":"죄란 무엇인가?","text":"죄를 짓는 자마다 불법을 행하나니 죄는 불법이라"},{"book":"요한일서","ref":"요한일서 5:13","topic":"우리에게 영생이 있음","text":"내가 하나님의 아들의 이름을 믿는 너희에게 이것을 쓰는 것은 너희로 하여금 너희에게 영생이 있음을 알게 하려 함이라"},{"book":"요한일서","ref":"요한일서 5:20","topic":"우리가 아는 것","text":"또 아는 것은 하나님의 아들이 이르러 우리에게 지각을 주사 우리로 참된 자를 알게 하신 것과 또한 / 우리가 참된 자 곧 그의 아들 예수 그리스도 안에 있는 것이니 그는 참 하나님이시요 영생이시라"},{"book":"요한이서","ref":"요한이서 1:5","topic":"서로 사랑하자","text":"부녀여, 내가 이제 네게 구하노니 서로 사랑하자 이는 새 계명 같이 네게 쓰는 것이 아니요 처음부터 우리가 가진 것이라"},{"book":"유다서","ref":"유다서 1:20","topic":"성령으로 기도하라","text":"사랑하는 자들아 너희는 너희의 지극히 거룩한 믿음 위에 자신을 세우며 성령으로 기도하며"},{"book":"유다서","ref":"유다서 1:21","topic":"성령으로 기도하라","text":"하나님의 사랑 안에서 자신을 지키며 영생에 이르도록 우리 주 예수 그리스도의 긍휼을 기다리라"},{"book":"요한계시록","ref":"요한계시록 1:7","topic":"그리스도의 재림","text":"볼지어다 그가 구름을 타고 오시리라 각 사람의 눈이 그를 보겠고 그를 찌른 자들도 볼 것이요 / 땅에 있는 모든 족속이 그로 말미암아 애곡하리니 그러하리라 아멘"},{"book":"요한계시록","ref":"요한계시록 7:17","topic":"우리의 목자 되신 어린 양","text":"이는 보좌 가운데에 계신 어린 양이 그들의 목자가 되사 생명수 샘으로 인도하시고 하나님께서 그들의 눈에서 모든 눈물을 씻어 주실 것임이라"},{"book":"요한계시록","ref":"요한계시록 14:13","topic":"성도의 복된 죽음","text":"또 내가 들으니 하늘에서 음성이 나서 이르되 기록하라 지금 이후로 주 안에서 죽는 자들은 복이 있도다 하시매 성령이 이르시되 그러하다 그들이 수고를 그치고 쉬리니 이는 그들의 행한 일이 따름이라 하시더라"},{"book":"요한계시록","ref":"요한계시록 19:16","topic":"만왕의 왕 만주의 주 되신 그리스도","text":"그 옷과 그 다리에 이름을 쓴 것이 있으니 만왕의 왕이요 / 만주의 주라 하였더라"},{"book":"요한계시록","ref":"요한계시록 21:5","topic":"만물을 새롭게 하심","text":"보좌에 앉으신 이가 이르시되 보라 내가 만물을 새롭게 하노라 하시고 또 이르시되 이 말은 신실하고 / 참되니 기록하라 하시고"}];
